-- ACL Basic Edition — Heart Failure, Acute Coronary Syndromes and Atrial Fibrillation
-- Safe to run more than once after the V2 Phase 2 migrations and Step 3.7–3.9 migration.
-- Adds three published undergraduate modules, six review cards per module,
-- 50 questions per module, question-specific Dr. Corazón hints, and subscription access.

begin;

create extension if not exists pgcrypto;

-- -----------------------------------------------------------------------------
-- Compatibility columns used by the dual-edition catalogue and learning player
-- -----------------------------------------------------------------------------

alter table public.modules
  add column if not exists edition text not null default 'expert';

alter table public.quizzes
  add column if not exists edition text not null default 'expert',
  add column if not exists pre_quiz_review_enabled boolean not null default false,
  add column if not exists pre_quiz_review_title text,
  add column if not exists pre_quiz_review_points jsonb not null default '[]'::jsonb,
  add column if not exists feedback_mode text not null default 'immediate',
  add column if not exists show_flashcards boolean not null default true,
  add column if not exists show_final_review boolean not null default true,
  add column if not exists require_review_before_next boolean not null default true;

alter table public.questions
  add column if not exists dr_corazon_hint text,
  add column if not exists flashcard_title text,
  add column if not exists flashcard_type text not null default 'FLASHCARD',
  add column if not exists flashcard_content jsonb not null default '{}'::jsonb;

alter table public.modules drop constraint if exists modules_edition_check;
alter table public.modules add constraint modules_edition_check
  check (edition in ('basic', 'expert'));

alter table public.quizzes drop constraint if exists quizzes_edition_check;
alter table public.quizzes add constraint quizzes_edition_check
  check (edition in ('basic', 'expert'));

alter table public.modules drop constraint if exists modules_access_type_check;
alter table public.modules add constraint modules_access_type_check
  check (access_type in ('open', 'subscription', 'passcode', 'minimum_score', 'admin_assigned'));

-- A subscription unlock uses the existing module_assignments table. This keeps
-- expiry, admin assignment, and revocation in the established access workflow.
create or replace function public.acl_module_access(p_module_id text)
returns table(allowed boolean, reason text)
language plpgsql
security definer
set search_path = public
as $$
declare
  m public.modules%rowtype;
  total_score numeric := 0;
  r record;
  user_position text;
  assigned boolean := false;
begin
  if not public.acl_is_active_user() then
    return query select false, 'Inactive account'::text;
    return;
  end if;

  select * into m from public.modules where id = p_module_id;
  if not found then
    return query select false, 'Module not found'::text;
    return;
  end if;

  if m.status <> 'published' then
    return query select false,
      case when m.status = 'coming_soon' then 'Coming soon' else 'Not published' end;
    return;
  end if;

  if m.opens_at is not null and now() < m.opens_at then
    return query select false, ('Opens ' || to_char(m.opens_at, 'YYYY-MM-DD HH24:MI'))::text;
    return;
  end if;

  if m.closes_at is not null and now() > m.closes_at then
    return query select false, 'Access window closed'::text;
    return;
  end if;

  select exists(
    select 1
    from public.module_assignments a
    where a.module_id = p_module_id
      and a.user_id = auth.uid()
      and (a.expires_at is null or a.expires_at > now())
  ) into assigned;

  select coalesce(sum(score), 0)
  into total_score
  from public.quiz_attempts
  where user_id = auth.uid() and status = 'completed';

  select academic_year into user_position
  from public.profiles
  where id = auth.uid();

  if m.access_type = 'subscription' and not assigned then
    return query select false, 'Subscription required'::text;
    return;
  end if;

  if m.access_type = 'admin_assigned' and not assigned then
    return query select false, 'Admin assignment required'::text;
    return;
  end if;

  if m.access_type = 'minimum_score' and total_score < coalesce(m.minimum_score, 0) then
    return query select false, ('Requires ' || m.minimum_score || ' points')::text;
    return;
  end if;

  if m.access_type = 'passcode' and not assigned then
    return query select false, 'Passcode or admin unlock required'::text;
    return;
  end if;

  for r in
    select * from public.module_unlock_rules
    where module_id = p_module_id and is_active
  loop
    if r.rule_type = 'prerequisite_module' and not exists (
      select 1 from public.quiz_attempts qa
      where qa.user_id = auth.uid()
        and qa.module_id = r.prerequisite_module_id
        and qa.status = 'completed'
    ) then
      return query select false,
        ('Complete prerequisite: ' || coalesce(
          (select title from public.modules where id = r.prerequisite_module_id),
          r.prerequisite_module_id
        ))::text;
      return;
    elsif r.rule_type = 'minimum_total_score' and total_score < coalesce(r.minimum_value, 0) then
      return query select false, ('Requires ' || r.minimum_value || ' total points')::text;
      return;
    elsif r.rule_type = 'academic_position'
      and coalesce(array_length(r.allowed_positions, 1), 0) > 0
      and not (user_position = any(r.allowed_positions)) then
      return query select false, 'Not available for your academic position'::text;
      return;
    elsif r.rule_type = 'manual_assignment' and not assigned then
      return query select false, 'Manual assignment required'::text;
      return;
    end if;
  end loop;

  return query select true, 'Available'::text;
end;
$$;

grant execute on function public.acl_module_access(text) to authenticated;

-- Secure learning retrieval now enforces module access and includes the
-- question-specific Dr. Corazón hint without exposing answer keys.
create or replace function public.acl_get_learning_quiz(p_quiz_slug text, p_module_id text default null)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  result jsonb;
  target_module_id text;
  access_allowed boolean;
  access_reason text;
begin
  if not public.acl_is_active_user() then
    raise exception 'Account is not active';
  end if;

  select z.module_id into target_module_id
  from public.quizzes z
  where z.slug = p_quiz_slug
    and (p_module_id is null or z.module_id = p_module_id)
    and z.status = 'published'
    and z.mode in ('learning', 'practice')
  limit 1;

  if target_module_id is null then
    raise exception 'Published learning quiz not found';
  end if;

  select a.allowed, a.reason
  into access_allowed, access_reason
  from public.acl_module_access(target_module_id) a;

  if not coalesce(access_allowed, false) then
    raise exception '%', coalesce(access_reason, 'Module access is restricted');
  end if;

  select jsonb_build_object(
    'id', z.id,
    'module_id', z.module_id,
    'slug', z.slug,
    'title', z.title,
    'description', z.description,
    'edition', z.edition,
    'mode', z.mode,
    'selection_mode', z.selection_mode,
    'question_count', z.question_count,
    'randomize_questions', z.randomize_questions,
    'randomize_options', z.randomize_options,
    'allow_review', z.allow_review,
    'show_explanations', z.show_explanations,
    'passing_percentage', z.passing_percentage,
    'module_title', m.title,
    'pre_quiz_review_enabled', z.pre_quiz_review_enabled,
    'pre_quiz_review_title', z.pre_quiz_review_title,
    'pre_quiz_review_points', z.pre_quiz_review_points,
    'questions', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', q.id,
        'question_type', q.question_type,
        'stem', q.stem,
        'clinical_scenario', q.clinical_scenario,
        'image_url', q.image_url,
        'image_alt', q.image_alt,
        'topic', q.topic,
        'subtopic', q.subtopic,
        'difficulty', q.difficulty,
        'points', coalesce(qq.points_override, q.points),
        'confidence_enabled', q.confidence_enabled,
        'display_order', qq.display_order,
        'dr_corazon_hint', q.dr_corazon_hint,
        'options', coalesce((
          select jsonb_agg(jsonb_build_object(
            'id', o.id,
            'key', o.option_key,
            'text', o.option_text,
            'image_url', o.image_url,
            'display_order', o.display_order
          ) order by o.display_order)
          from public.question_options o
          where o.question_id = q.id
        ), '[]'::jsonb)
      ) order by qq.display_order)
      from public.quiz_questions qq
      join public.questions q on q.id = qq.question_id
      where qq.quiz_id = z.id and q.status = 'published'
    ), '[]'::jsonb)
  ) into result
  from public.quizzes z
  join public.modules m on m.id = z.module_id
  where z.slug = p_quiz_slug
    and z.module_id = target_module_id
    and z.status = 'published'
    and z.mode in ('learning', 'practice')
    and m.status = 'published';

  if result is null then
    raise exception 'Published learning quiz not found';
  end if;

  return result;
end;
$$;

grant execute on function public.acl_get_learning_quiz(text, text) to authenticated;

-- Enforce the same access rule when an answer is checked, so a restricted quiz
-- cannot be used through a hand-crafted direct RPC call.
create or replace function public.acl_check_learning_answer(
  p_quiz_id uuid,
  p_question_id uuid,
  p_option_ids uuid[]
)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  q record;
  correct_ids uuid[];
  chosen uuid[];
  ok boolean;
  target_module_id text;
  access_allowed boolean;
  access_reason text;
begin
  if not public.acl_is_active_user() then
    raise exception 'Account is not active';
  end if;

  select z.module_id
  into target_module_id
  from public.quizzes z
  where z.id = p_quiz_id
    and z.status = 'published'
    and z.mode in ('learning', 'practice');

  if target_module_id is null then
    raise exception 'Quiz is not available';
  end if;

  select a.allowed, a.reason
  into access_allowed, access_reason
  from public.acl_module_access(target_module_id) a;

  if not coalesce(access_allowed, false) then
    raise exception '%', coalesce(access_reason, 'Module access is restricted');
  end if;

  select
    qu.question_type,
    qu.explanation,
    qu.reference_text,
    qu.reference_url,
    coalesce(qq.points_override, qu.points) as points
  into q
  from public.quiz_questions qq
  join public.questions qu on qu.id = qq.question_id
  join public.quizzes z on z.id = qq.quiz_id
  where qq.quiz_id = p_quiz_id
    and qq.question_id = p_question_id
    and z.module_id = target_module_id
    and z.status = 'published'
    and z.mode in ('learning', 'practice');

  if not found then
    raise exception 'Question is not available in this quiz';
  end if;

  select coalesce(array_agg(id order by id), '{}'::uuid[])
  into correct_ids
  from public.question_options
  where question_id = p_question_id and is_correct;

  select coalesce(array_agg(x order by x), '{}'::uuid[])
  into chosen
  from unnest(coalesce(p_option_ids, '{}'::uuid[])) x;

  ok := chosen = correct_ids;

  return jsonb_build_object(
    'correct', ok,
    'points', case when ok then q.points else 0 end,
    'correct_option_ids', correct_ids,
    'explanation', q.explanation,
    'reference_text', q.reference_text,
    'reference_url', q.reference_url
  );
end;
$$;

grant execute on function public.acl_check_learning_answer(uuid, uuid, uuid[]) to authenticated;

-- -----------------------------------------------------------------------------
-- Modules
-- -----------------------------------------------------------------------------

insert into public.modules (
  id, slug, title, description, short_description, full_description,
  category, difficulty, estimated_minutes, question_count, status,
  access_type, minimum_score, learning_mode_enabled,
  competition_mode_enabled, display_order, is_featured, launch_path, edition
) values
(
  'basic-heart-failure', 'basic-heart-failure', 'Heart Failure',
  'Undergraduate foundations of heart failure diagnosis, treatment and patient counselling.',
  'Recognize, investigate and manage heart failure at undergraduate level.',
  'Definition, causes, symptoms and signs, diagnosis, treatment, monitoring, safety-netting and patient counselling.',
  'General Cardiology', 'foundation', 90, 50, 'published', 'open', 0,
  true, false, 1, true,
  'learning.html?module=basic-heart-failure&quiz=basic-heart-failure-50', 'basic'
),
(
  'basic-atrial-fibrillation', 'basic-atrial-fibrillation', 'Atrial Fibrillation',
  'Undergraduate foundations of atrial fibrillation diagnosis, stroke prevention and symptom control.',
  'Recognize AF, assess risk and explain treatment clearly to patients.',
  'Definition, causes, presentation, ECG diagnosis, stroke and bleeding assessment, rate or rhythm control, anticoagulation and counselling.',
  'ECG and Rhythm', 'foundation', 90, 50, 'published', 'open', 0,
  true, false, 2, true,
  'learning.html?module=basic-atrial-fibrillation&quiz=basic-atrial-fibrillation-50', 'basic'
),
(
  'basic-acute-coronary-syndromes', 'basic-acute-coronary-syndromes', 'Acute Coronary Syndromes',
  'Undergraduate recognition and initial management of STEMI, NSTEMI and unstable angina.',
  'Diagnose ACS, begin safe initial care and understand reperfusion pathways.',
  'Definition, causes, symptoms and signs, ECG and troponin diagnosis, immediate treatment, reperfusion, complications, secondary prevention and counselling.',
  'Ischaemic Heart Disease', 'foundation', 100, 50, 'published', 'subscription', 0,
  true, false, 3, true,
  'learning.html?module=basic-acute-coronary-syndromes&quiz=basic-acute-coronary-syndromes-50', 'basic'
)
on conflict (id) do update set
  slug = excluded.slug,
  title = excluded.title,
  description = excluded.description,
  short_description = excluded.short_description,
  full_description = excluded.full_description,
  category = excluded.category,
  difficulty = excluded.difficulty,
  estimated_minutes = excluded.estimated_minutes,
  question_count = excluded.question_count,
  status = excluded.status,
  access_type = excluded.access_type,
  minimum_score = excluded.minimum_score,
  learning_mode_enabled = excluded.learning_mode_enabled,
  competition_mode_enabled = excluded.competition_mode_enabled,
  display_order = excluded.display_order,
  is_featured = excluded.is_featured,
  launch_path = excluded.launch_path,
  edition = excluded.edition,
  updated_at = now();

-- -----------------------------------------------------------------------------
-- Quizzes and detailed undergraduate review cards
-- -----------------------------------------------------------------------------

insert into public.quizzes (
  module_id, slug, title, description, edition, mode, selection_mode,
  question_count, randomize_questions, randomize_options, allow_review,
  show_explanations, passing_percentage, status, display_order,
  pre_quiz_review_enabled, pre_quiz_review_title, pre_quiz_review_points,
  feedback_mode, show_flashcards, show_final_review, require_review_before_next
) values
(
  'basic-heart-failure', 'basic-heart-failure-50',
  'Heart Failure — Undergraduate Question Bank',
  'Fifty single-best-answer questions with immediate explanations and Dr. Corazón guidance.',
  'basic', 'learning', 'fixed', 50, false, true, true, true, 70, 'published', 1,
  true, 'Dr. Corazón’s Heart Failure Review',
  $json$[
    {"title":"Definition and classification","summary":"What heart failure means and how it is classified","content":["Heart failure is a clinical syndrome caused by a structural or functional cardiac abnormality.","The syndrome produces typical symptoms such as breathlessness, ankle swelling and fatigue.","Typical signs include raised jugular venous pressure, pulmonary crackles and peripheral oedema.","Objective evidence of cardiac dysfunction or raised filling pressure supports the diagnosis.","HFrEF usually means left ventricular ejection fraction 40% or less.","HFmrEF generally means ejection fraction 41–49% with supporting evidence of heart failure.","HFpEF generally means ejection fraction 50% or more with evidence of raised filling pressure or structural disease.","Left-sided failure commonly produces pulmonary congestion.","Right-sided failure commonly produces systemic venous congestion.","Acute heart failure develops rapidly or represents sudden worsening.","Chronic heart failure is persistent and requires long-term treatment and monitoring.","Ejection fraction helps classify heart failure but does not replace clinical assessment."]},
    {"title":"Causes and precipitants","summary":"Identify the disease and the trigger","content":["Ischaemic heart disease and previous myocardial infarction are common causes of HFrEF.","Long-standing hypertension may cause hypertrophy, diastolic dysfunction and eventually systolic failure.","Valvular disease can produce pressure or volume overload.","Cardiomyopathies may be dilated, hypertrophic, restrictive, inflammatory, toxic or inherited.","Persistent tachyarrhythmia can cause or worsen ventricular dysfunction.","Alcohol, selected chemotherapy and some toxins may damage myocardium.","Congenital and pericardial disease are less common but important causes.","Common precipitants of decompensation include infection, acute ischaemia and uncontrolled hypertension.","Rapid atrial fibrillation may abruptly worsen symptoms.","Poor adherence to medicines or excess dietary salt can cause congestion.","Renal dysfunction, anaemia and thyroid disease may aggravate heart failure.","Always identify both the underlying cause and the reversible precipitant."]},
    {"title":"Symptoms and signs","summary":"Recognize congestion, low output and red flags","content":["Exertional breathlessness is common but not specific.","Orthopnoea is breathlessness when lying flat and suggests pulmonary congestion.","Paroxysmal nocturnal dyspnoea wakes the patient from sleep with breathlessness.","Fatigue and reduced exercise tolerance may reflect low cardiac output.","Ankle swelling and rapid weight gain suggest fluid retention.","Nocturia, abdominal fullness and early satiety may occur.","Raised jugular venous pressure is an important sign of systemic congestion.","Bibasal crackles may indicate pulmonary oedema, although they can be absent in chronic HF.","A displaced apex beat suggests cardiac enlargement.","A third heart sound may occur with volume overload and systolic dysfunction.","Cool extremities, confusion, oliguria and hypotension suggest hypoperfusion.","Severe breathlessness at rest, syncope, chest pain or shock requires urgent escalation."]},
    {"title":"Diagnosis","summary":"Confirm the syndrome and find its cause","content":["Begin with history, examination and assessment of clinical probability.","Obtain a 12-lead ECG; a completely normal ECG makes HF less likely.","Measure natriuretic peptides when the diagnosis is uncertain; low values make HF less likely.","Remember that age, atrial fibrillation and renal dysfunction can raise natriuretic peptides.","Obesity can produce lower natriuretic peptide concentrations.","Echocardiography assesses ejection fraction, chamber size, valves, wall motion and filling pressure clues.","Chest X-ray may show cardiomegaly, pulmonary venous congestion or alternative lung disease.","Routine blood tests include full blood count, renal function, electrolytes, liver function, glucose or HbA1c and thyroid function.","Troponin is useful when acute coronary syndrome or myocardial injury is suspected.","Consider coronary assessment when ischaemic disease is possible.","Assess iron status because iron deficiency is common and treatable.","Diagnosis requires integration; no single symptom, sign or test is sufficient alone."]},
    {"title":"Treatment","summary":"Relieve congestion, improve outcomes and treat the cause","content":["Treat the underlying cause and any acute precipitant.","Loop diuretics relieve fluid overload and symptoms but require renal and electrolyte monitoring.","For HFrEF, foundational disease-modifying therapy includes an ACE inhibitor or ARNI, an evidence-based beta-blocker, an MRA and an SGLT2 inhibitor when appropriate.","Start and titrate disease-modifying medicines according to blood pressure, renal function, potassium and tolerance.","Do not start or increase a beta-blocker during shock or severe unstable congestion.","SGLT2 inhibitors improve outcomes in heart failure across a broad range of ejection fraction.","Selected patients may need ivabradine, hydralazine–nitrate therapy or digoxin.","Treat hypertension, diabetes, coronary disease, valvular disease, AF and iron deficiency.","Devices such as ICD or CRT are considered in selected patients after optimized therapy.","Acute pulmonary oedema requires urgent assessment, oxygen only when hypoxaemic, diuresis and treatment of the cause.","Avoid NSAIDs where possible because they may cause sodium retention and renal deterioration.","Cardiac rehabilitation, vaccination and multidisciplinary follow-up improve comprehensive care."]},
    {"title":"How to counsel patients","summary":"Explain self-care, monitoring and when to seek help","content":["Use clear language: the heart is not pumping or filling as effectively as it should.","Explain the cause and whether ejection fraction is reduced, mildly reduced or preserved.","Clarify that medicines may improve survival even when the patient feels well.","Provide a written medication list and explain the purpose of each drug.","Discuss expected effects and important adverse effects without encouraging abrupt self-discontinuation.","Encourage daily weight monitoring when practical and recognition of rapid weight gain.","Teach the patient to notice worsening breathlessness, swelling, orthopnoea and reduced urine output.","Advise urgent help for severe breathlessness, fainting, chest pain, confusion or blue lips.","Discuss salt moderation and individualized fluid advice rather than extreme restriction for everyone.","Encourage regular activity or cardiac rehabilitation when clinically stable.","Support smoking cessation and moderation or avoidance of alcohol as appropriate.","Involve family or carers with the patient’s permission and use shared decisions for advanced treatments."]}
  ]$json$::jsonb,
  'immediate', true, true, true
),
(
  'basic-atrial-fibrillation', 'basic-atrial-fibrillation-50',
  'Atrial Fibrillation — Undergraduate Question Bank',
  'Fifty single-best-answer questions with immediate explanations and Dr. Corazón guidance.',
  'basic', 'learning', 'fixed', 50, false, true, true, true, 70, 'published', 1,
  true, 'Dr. Corazón’s Atrial Fibrillation Review',
  $json$[
    {"title":"Definition and classification","summary":"Define AF and describe its clinical patterns","content":["Atrial fibrillation is a supraventricular tachyarrhythmia with chaotic atrial activation and ineffective atrial contraction.","The ECG shows irregular RR intervals when AV conduction is present.","Discrete, repeating P waves are absent.","An episode should be documented on an ECG tracing before a clinical diagnosis is made.","First-diagnosed AF is the first recognized episode regardless of duration.","Paroxysmal AF terminates spontaneously or with intervention within seven days.","Persistent AF lasts more than seven days or requires cardioversion after that period.","Long-standing persistent AF continues for at least twelve months when rhythm control is still pursued.","Permanent AF means patient and clinician accept AF and do not pursue further rhythm restoration.","AF may be symptomatic or silent.","The ventricular rate may be fast, normal or slow depending on AV conduction and medicines.","Classification describes the pattern but stroke risk is assessed separately."]},
    {"title":"Causes and risk factors","summary":"Look for cardiac disease, systemic triggers and modifiable risks","content":["Increasing age is a major risk factor.","Hypertension, heart failure, coronary disease and valvular disease are common associations.","Mitral stenosis and left atrial enlargement strongly predispose to AF.","Obesity and obstructive sleep apnoea promote AF development and recurrence.","Diabetes, chronic kidney disease and excess alcohol increase risk.","Hyperthyroidism is an important reversible cause.","Acute infection, surgery, pulmonary embolism and myocardial infarction may trigger AF.","Stimulants and binge alcohol can precipitate episodes.","Some patients have no obvious structural heart disease.","Ask about family history in younger patients.","Risk-factor treatment reduces symptoms and improves rhythm-control success.","Do not assume that AF caused by an acute trigger carries no future recurrence or stroke risk."]},
    {"title":"Symptoms and signs","summary":"Recognize AF and assess haemodynamic stability","content":["Palpitations are common but not universal.","Breathlessness, fatigue and reduced exercise capacity may dominate.","Dizziness, presyncope or syncope may occur, especially with extreme rates.","Chest discomfort can accompany rapid AF or underlying coronary disease.","Some patients present with stroke, systemic embolism or heart failure.","The pulse is classically irregularly irregular.","There may be a pulse deficit between apical and radial rates.","The intensity of the first heart sound may vary.","Look for signs of heart failure, valvular disease, thyroid disease and infection.","Hypotension, ongoing ischaemic chest pain, pulmonary oedema or shock indicates instability.","A very slow rate may reflect conduction disease or excessive rate-control medication.","Symptoms do not reliably indicate episode duration, so anticoagulation decisions need objective assessment."]},
    {"title":"Diagnosis and assessment","summary":"Confirm AF, identify causes and assess stroke and bleeding risk","content":["Confirm the rhythm with a 12-lead ECG or a rhythm strip of adequate quality.","AF shows absent organized P waves and irregular ventricular activation.","Ambulatory monitoring can detect intermittent AF when a standard ECG is normal.","Assess onset, pattern, symptom burden and haemodynamic effect.","Measure full blood count, renal function, electrolytes and thyroid function when appropriate.","Echocardiography evaluates chamber size, ventricular function and valve disease.","Use an accepted thromboembolic risk score to guide anticoagulation decisions.","The 2024 ESC approach uses CHA2DS2-VA, while many settings still use CHA2DS2-VASc; follow local guidance.","Assess bleeding risk factors to correct modifiable hazards, not simply to deny anticoagulation.","Review renal function and weight when selecting and dosing a DOAC.","Ask about falls, previous bleeding, adherence and interacting medicines.","Reassess stroke and bleeding risk periodically because both change over time."]},
    {"title":"Treatment","summary":"Use AF-CARE: comorbidities, anticoagulation, symptoms and reassessment","content":["Treat cardiovascular and other comorbidities, including blood pressure, obesity, sleep apnoea and alcohol excess.","Prevent stroke with oral anticoagulation when thromboembolic risk justifies it.","DOACs are generally preferred over vitamin K antagonists except in mechanical valves or moderate-to-severe rheumatic mitral stenosis.","Use the correct DOAC dose; inappropriate dose reduction can reduce protection.","Antiplatelet therapy is not an adequate substitute for anticoagulation in AF stroke prevention.","Rate control may use a beta-blocker, diltiazem or verapamil in appropriate patients, or digoxin in selected situations.","Avoid verapamil or diltiazem in HFrEF.","Rhythm control may include cardioversion, antiarrhythmic drugs or catheter ablation.","Urgent synchronized cardioversion is indicated when AF causes haemodynamic instability.","Plan anticoagulation around cardioversion according to AF duration and thromboembolic risk.","Catheter ablation is effective for symptom improvement in selected patients.","Reassess symptoms, rate, rhythm, stroke risk, bleeding risk and treatment adherence regularly."]},
    {"title":"How to counsel patients","summary":"Explain rhythm, stroke prevention and safety clearly","content":["Explain that the upper chambers beat irregularly and do not contract normally.","Separate two treatment goals: reducing stroke risk and improving symptoms.","Clarify that feeling well does not necessarily mean stroke risk has disappeared.","Explain the benefit and bleeding risk of anticoagulation using shared decisions.","Teach the patient not to stop anticoagulation without clinical advice.","Review missed-dose instructions for the specific anticoagulant.","Warn about bleeding red flags such as vomiting blood, black stools, severe headache after trauma or persistent bleeding.","Encourage the patient to tell dentists and clinicians about anticoagulation.","Discuss pulse awareness and when palpitations require assessment.","Advise urgent help for chest pain, severe breathlessness, fainting, weakness of one side or speech disturbance.","Encourage blood-pressure control, healthy weight, activity, sleep-apnoea assessment and reduced excess alcohol.","Agree whether the main symptom strategy is rate control, rhythm control or both, and arrange reassessment."]}
  ]$json$::jsonb,
  'immediate', true, true, true
),
(
  'basic-acute-coronary-syndromes', 'basic-acute-coronary-syndromes-50',
  'Acute Coronary Syndromes — Undergraduate Question Bank',
  'Fifty single-best-answer questions with immediate explanations and Dr. Corazón guidance.',
  'basic', 'learning', 'fixed', 50, false, true, true, true, 70, 'published', 1,
  true, 'Dr. Corazón’s Acute Coronary Syndromes Review',
  $json$[
    {"title":"Definition and classification","summary":"Understand STEMI, NSTEMI and unstable angina","content":["Acute coronary syndrome is a spectrum of acute myocardial ischaemia usually caused by coronary atherothrombosis.","The clinical spectrum includes STEMI, NSTEMI and unstable angina.","Myocardial infarction requires acute myocardial injury with clinical evidence of ischaemia.","A rise or fall in cardiac troponin with at least one value above the 99th percentile indicates acute myocardial injury.","STEMI is diagnosed from the clinical presentation and persistent ST-segment elevation or an accepted equivalent requiring immediate reperfusion assessment.","NSTEMI has myocardial necrosis without persistent ST elevation.","Unstable angina causes ischaemic symptoms without biomarker evidence of myocardial necrosis.","High-sensitivity troponin has reduced the proportion labelled unstable angina.","Type 1 MI usually results from plaque rupture or erosion with thrombosis.","Type 2 MI results from oxygen supply–demand imbalance without acute coronary atherothrombosis.","Cardiac arrest, shock or refractory pain may indicate a very-high-risk ACS presentation.","Initial classification guides urgency but patients require repeated reassessment."]},
    {"title":"Causes and risk factors","summary":"Recognize atherothrombosis, mimics and contributors","content":["Plaque rupture with superimposed thrombosis is the classic mechanism of type 1 MI.","Plaque erosion can also produce coronary thrombosis.","Less common coronary causes include spontaneous coronary artery dissection, embolism and vasospasm.","Fixed atherosclerosis may become critical during increased demand.","Smoking, hypertension, diabetes and dyslipidaemia are major modifiable risks.","Age, male sex and family history contribute to baseline risk.","Chronic kidney disease and inflammatory disease increase cardiovascular risk.","Cocaine and other stimulants may provoke vasospasm or thrombosis.","Anaemia, hypoxaemia, sepsis and tachyarrhythmia may cause type 2 MI.","Not every troponin rise is MI; myocarditis, heart failure, pulmonary embolism and renal disease can cause injury.","Women, older adults and people with diabetes may present atypically.","Always assess the whole clinical picture rather than treating an isolated biomarker."]},
    {"title":"Symptoms and signs","summary":"Recognize typical, atypical and high-risk presentations","content":["Typical discomfort is central pressure, heaviness or tightness lasting more than a few minutes.","Pain may radiate to one or both arms, neck, jaw, back or epigastrium.","Associated symptoms include sweating, nausea, breathlessness and a sense of impending doom.","Symptoms at rest, new severe angina or crescendo angina are concerning.","Dyspnoea, collapse, confusion or unexplained weakness may be the main presentation.","A normal physical examination does not exclude ACS.","Hypotension, cool peripheries and altered consciousness suggest shock.","Pulmonary crackles or hypoxaemia may indicate acute heart failure.","A new murmur may signal acute mitral regurgitation or ventricular septal rupture.","Unequal pulses or tearing pain raises concern for aortic dissection.","Pleuritic pain and tachycardia may suggest pulmonary embolism, but overlap occurs.","Ongoing pain, dynamic ECG change, arrhythmia or instability requires immediate escalation."]},
    {"title":"Diagnosis","summary":"Use ECG, serial troponin and clinical probability together","content":["Obtain and interpret a 12-lead ECG as early as possible, ideally within ten minutes of first medical contact.","Repeat the ECG if symptoms continue or the initial tracing is nondiagnostic.","Persistent ST elevation in appropriate leads suggests acute coronary occlusion.","ST depression and T-wave inversion may indicate ischaemia but are not specific.","Posterior or right-sided leads can reveal infarction missed on the standard ECG.","Measure high-sensitivity cardiac troponin using a validated rapid rule-in/rule-out algorithm.","A single normal early troponin does not always exclude MI.","Interpret troponin change, timing and clinical context.","Take a focused history for onset, quality, risk factors, bleeding risk and alternative diagnoses.","Bedside echocardiography can identify wall-motion abnormality and mechanical complications but should not delay reperfusion.","Chest X-ray helps assess alternatives or complications when indicated.","Risk scores support but do not replace clinical judgement."]},
    {"title":"Treatment","summary":"Stabilize, inhibit thrombosis and restore coronary flow","content":["Assess airway, breathing, circulation, pain, rhythm and haemodynamic status immediately.","Give oxygen only when hypoxaemia, respiratory distress or another clear indication is present.","Give aspirin promptly unless contraindicated.","Add a P2Y12 inhibitor according to the ACS strategy, bleeding risk and local protocol.","Use parenteral anticoagulation as indicated for the chosen invasive or reperfusion pathway.","Nitrates may relieve pain but avoid them in hypotension, suspected right ventricular infarction or recent PDE5-inhibitor use.","Use opioid analgesia selectively for severe persistent pain because it may delay oral antiplatelet absorption.","STEMI requires immediate reperfusion planning, preferably timely primary PCI.","If timely PCI is impossible in an eligible early STEMI presentation, fibrinolysis may be considered with urgent transfer.","Very-high-risk NSTE-ACS requires an immediate invasive strategy; high-risk patients generally need early angiography.","Start high-intensity lipid-lowering therapy and secondary prevention.","Monitor for arrhythmia, heart failure, recurrent ischaemia, bleeding and mechanical complications."]},
    {"title":"How to counsel patients","summary":"Explain urgency, treatment, recovery and prevention","content":["Explain that blood flow to part of the heart has been suddenly reduced or blocked.","Use calm, direct language and emphasize why rapid treatment matters.","Before procedures, explain benefits, common risks and alternatives as the clinical situation allows.","Clarify the purpose and expected duration of dual antiplatelet therapy.","Warn not to stop antiplatelet treatment after stenting without urgent specialist advice.","Explain bleeding warning signs and when to seek help.","Review chest-pain safety-netting: call emergency services for recurrent severe or persistent symptoms.","Discuss cardiac rehabilitation and gradual return to activity.","Support smoking cessation, healthy diet, physical activity, blood-pressure control and diabetes care.","Explain the role of statins and other secondary-prevention medicines even when cholesterol or symptoms improve.","Discuss return to work, driving and sexual activity using local rules and individualized advice.","Use teach-back: ask the patient to repeat the medication and emergency plan in their own words."]}
  ]$json$::jsonb,
  'immediate', true, true, true
)
on conflict (module_id, slug) do update set
  title = excluded.title,
  description = excluded.description,
  edition = excluded.edition,
  mode = excluded.mode,
  selection_mode = excluded.selection_mode,
  question_count = excluded.question_count,
  randomize_questions = excluded.randomize_questions,
  randomize_options = excluded.randomize_options,
  allow_review = excluded.allow_review,
  show_explanations = excluded.show_explanations,
  passing_percentage = excluded.passing_percentage,
  status = excluded.status,
  display_order = excluded.display_order,
  pre_quiz_review_enabled = excluded.pre_quiz_review_enabled,
  pre_quiz_review_title = excluded.pre_quiz_review_title,
  pre_quiz_review_points = excluded.pre_quiz_review_points,
  feedback_mode = excluded.feedback_mode,
  show_flashcards = excluded.show_flashcards,
  show_final_review = excluded.show_final_review,
  require_review_before_next = excluded.require_review_before_next,
  updated_at = now();

-- -----------------------------------------------------------------------------
-- Question seed. Four options are used consistently for undergraduate SBA style.
-- Difficulty values remain inside the existing foundation/intermediate/advanced set.
-- -----------------------------------------------------------------------------

create temporary table acl_basic_question_seed (
  module_id text,
  external_id text,
  stem text,
  clinical_scenario text,
  topic text,
  subtopic text,
  difficulty text,
  explanation text,
  reference_text text,
  reference_url text,
  dr_corazon_hint text,
  display_order integer,
  options jsonb
) on commit drop;

-- Heart Failure: 50 questions
insert into acl_basic_question_seed
select * from jsonb_to_recordset($questions$
[
  {"module_id":"basic-heart-failure","external_id":"basic-hf-001","stem":"Which statement best defines heart failure?","clinical_scenario":null,"topic":"Definition","subtopic":"Clinical syndrome","difficulty":"foundation","explanation":"Heart failure is a clinical syndrome caused by a structural or functional cardiac abnormality, producing symptoms or signs supported by objective evidence of dysfunction or raised filling pressures.","reference_text":"2021 ESC Heart Failure Guidelines and 2023 Focused Update","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/focused-update-on-heart-failure/","dr_corazon_hint":"Look for the option that combines a clinical syndrome with an underlying cardiac abnormality; ejection fraction alone is not the definition.","display_order":1,"options":[{"key":"A","text":"Any left ventricular ejection fraction below 50%","correct":false},{"key":"B","text":"A clinical syndrome due to cardiac abnormality causing typical symptoms or signs","correct":true},{"key":"C","text":"Pulmonary oedema caused only by myocardial infarction","correct":false},{"key":"D","text":"Any patient with ankle oedema and hypertension","correct":false}]},
  {"module_id":"basic-heart-failure","external_id":"basic-hf-002","stem":"Which left ventricular ejection fraction is most consistent with HFrEF?","clinical_scenario":null,"topic":"Definition","subtopic":"Ejection fraction","difficulty":"foundation","explanation":"HFrEF is generally defined by LVEF 40% or less.","reference_text":"2021 ESC Heart Failure Guidelines","reference_url":"https://www.escardio.org/topics/heart-failure/","dr_corazon_hint":"Remember the undergraduate threshold: reduced ejection fraction is 40% or below.","display_order":2,"options":[{"key":"A","text":"35%","correct":true},{"key":"B","text":"45%","correct":false},{"key":"C","text":"52%","correct":false},{"key":"D","text":"65%","correct":false}]},
  {"module_id":"basic-heart-failure","external_id":"basic-hf-003","stem":"A patient has an LVEF of 55%, symptoms of heart failure, left atrial enlargement and raised filling pressures. What is the most appropriate phenotype?","clinical_scenario":"A 72-year-old patient has exertional dyspnoea, preserved LVEF and objective evidence of raised filling pressure.","topic":"Definition","subtopic":"HFpEF","difficulty":"intermediate","explanation":"Symptoms or signs of HF with LVEF at least 50% and objective evidence of structural disease or raised filling pressure support HFpEF.","reference_text":"2021 ESC Heart Failure Guidelines","reference_url":"https://www.escardio.org/topics/heart-failure/","dr_corazon_hint":"Preserved EF does not exclude heart failure; look for objective evidence of abnormal filling pressure or structural disease.","display_order":3,"options":[{"key":"A","text":"HFrEF","correct":false},{"key":"B","text":"HFmrEF","correct":false},{"key":"C","text":"HFpEF","correct":true},{"key":"D","text":"No heart failure because EF is normal","correct":false}]},
  {"module_id":"basic-heart-failure","external_id":"basic-hf-004","stem":"Which is the most common underlying cause of HFrEF in many adult populations?","clinical_scenario":null,"topic":"Causes","subtopic":"Aetiology","difficulty":"foundation","explanation":"Ischaemic heart disease and prior myocardial infarction are major causes of HFrEF.","reference_text":"2021 ESC Heart Failure Guidelines","reference_url":"https://www.escardio.org/topics/heart-failure/","dr_corazon_hint":"Think of the disease that directly destroys ventricular myocardium and leaves regional or global systolic dysfunction.","display_order":4,"options":[{"key":"A","text":"Ischaemic heart disease","correct":true},{"key":"B","text":"Allergic rhinitis","correct":false},{"key":"C","text":"Uncomplicated appendicitis","correct":false},{"key":"D","text":"Migraine","correct":false}]},
  {"module_id":"basic-heart-failure","external_id":"basic-hf-005","stem":"Which condition commonly causes heart failure through chronic pressure overload?","clinical_scenario":null,"topic":"Causes","subtopic":"Hypertension","difficulty":"foundation","explanation":"Long-standing hypertension produces pressure overload, hypertrophy and later systolic or diastolic dysfunction.","reference_text":"2021 ESC Heart Failure Guidelines","reference_url":"https://www.escardio.org/topics/heart-failure/","dr_corazon_hint":"Choose the common condition that forces the left ventricle to pump against persistently increased afterload.","display_order":5,"options":[{"key":"A","text":"Hypertension","correct":true},{"key":"B","text":"Iron-deficiency without anaemia","correct":false},{"key":"C","text":"Simple renal cyst","correct":false},{"key":"D","text":"Myopia","correct":false}]},
  {"module_id":"basic-heart-failure","external_id":"basic-hf-006","stem":"Which drug exposure is a recognized potential cause of cardiomyopathy?","clinical_scenario":null,"topic":"Causes","subtopic":"Toxic cardiomyopathy","difficulty":"foundation","explanation":"Anthracycline chemotherapy such as doxorubicin can cause dose-related myocardial injury and cardiomyopathy.","reference_text":"2021 ESC Heart Failure Guidelines","reference_url":"https://www.escardio.org/topics/heart-failure/","dr_corazon_hint":"Think of the chemotherapy class well known for cumulative myocardial toxicity.","display_order":6,"options":[{"key":"A","text":"Doxorubicin","correct":true},{"key":"B","text":"Oral rehydration salts","correct":false},{"key":"C","text":"Topical emollient","correct":false},{"key":"D","text":"Paracetamol at standard dose","correct":false}]},
  {"module_id":"basic-heart-failure","external_id":"basic-hf-007","stem":"Which is a common precipitant of acute decompensation in a patient with chronic heart failure?","clinical_scenario":null,"topic":"Causes","subtopic":"Precipitants","difficulty":"foundation","explanation":"Infection commonly triggers decompensation through increased metabolic demand, inflammation and fluid or haemodynamic changes.","reference_text":"2021 ESC Heart Failure Guidelines","reference_url":"https://www.escardio.org/topics/heart-failure/","dr_corazon_hint":"Separate the chronic cause of HF from an acute trigger; infection is one of the classic reversible precipitants.","display_order":7,"options":[{"key":"A","text":"Pneumonia","correct":true},{"key":"B","text":"Stable corrected myopia","correct":false},{"key":"C","text":"Remote appendicectomy","correct":false},{"key":"D","text":"A healed ankle sprain","correct":false}]},
  {"module_id":"basic-heart-failure","external_id":"basic-hf-008","stem":"Which rhythm disturbance can both cause and worsen heart failure when sustained with a rapid ventricular rate?","clinical_scenario":null,"topic":"Causes","subtopic":"Arrhythmia","difficulty":"foundation","explanation":"Persistent rapid atrial fibrillation can cause tachycardia-mediated cardiomyopathy and precipitate decompensation.","reference_text":"2021 ESC Heart Failure Guidelines","reference_url":"https://www.escardio.org/topics/heart-failure/","dr_corazon_hint":"Look for a common tachyarrhythmia that may reduce filling time and, when persistent, impair ventricular function.","display_order":8,"options":[{"key":"A","text":"Atrial fibrillation with rapid ventricular response","correct":true},{"key":"B","text":"Sinus arrhythmia in a young adult","correct":false},{"key":"C","text":"First-degree AV block alone","correct":false},{"key":"D","text":"Occasional isolated atrial ectopics","correct":false}]},
  {"module_id":"basic-heart-failure","external_id":"basic-hf-009","stem":"Which symptom most specifically suggests pulmonary congestion in heart failure?","clinical_scenario":null,"topic":"Symptoms and signs","subtopic":"Orthopnoea","difficulty":"foundation","explanation":"Orthopnoea—breathlessness when lying flat that improves on sitting up—is characteristic of pulmonary congestion.","reference_text":"2021 ESC Heart Failure Guidelines","reference_url":"https://www.escardio.org/topics/heart-failure/","dr_corazon_hint":"Ask what happens when the patient lies flat; redistribution of venous blood can worsen pulmonary congestion.","display_order":9,"options":[{"key":"A","text":"Orthopnoea","correct":true},{"key":"B","text":"Isolated sneezing","correct":false},{"key":"C","text":"Photophobia","correct":false},{"key":"D","text":"Dysuria","correct":false}]},
  {"module_id":"basic-heart-failure","external_id":"basic-hf-010","stem":"What does paroxysmal nocturnal dyspnoea describe?","clinical_scenario":null,"topic":"Symptoms and signs","subtopic":"PND","difficulty":"foundation","explanation":"PND is sudden breathlessness that wakes a patient from sleep, often relieved by sitting or standing.","reference_text":"2021 ESC Heart Failure Guidelines","reference_url":"https://www.escardio.org/topics/heart-failure/","dr_corazon_hint":"The key clue is awakening from sleep with breathlessness rather than breathlessness only on exertion.","display_order":10,"options":[{"key":"A","text":"Breathlessness waking the patient from sleep","correct":true},{"key":"B","text":"Cough only after eating","correct":false},{"key":"C","text":"Daytime sleepiness without dyspnoea","correct":false},{"key":"D","text":"Chest pain lasting one second","correct":false}]},
  {"module_id":"basic-heart-failure","external_id":"basic-hf-011","stem":"Which bedside sign is particularly useful for detecting systemic venous congestion?","clinical_scenario":null,"topic":"Symptoms and signs","subtopic":"Congestion","difficulty":"foundation","explanation":"Raised jugular venous pressure reflects elevated right atrial pressure and systemic venous congestion.","reference_text":"2021 ESC Heart Failure Guidelines","reference_url":"https://www.escardio.org/topics/heart-failure/","dr_corazon_hint":"Choose the neck examination finding that estimates right atrial pressure.","display_order":11,"options":[{"key":"A","text":"Raised jugular venous pressure","correct":true},{"key":"B","text":"Absent ankle reflexes","correct":false},{"key":"C","text":"Hyperresonant percussion only","correct":false},{"key":"D","text":"Positive Babinski sign","correct":false}]},
  {"module_id":"basic-heart-failure","external_id":"basic-hf-012","stem":"Which finding suggests hypoperfusion rather than congestion?","clinical_scenario":null,"topic":"Symptoms and signs","subtopic":"Low output","difficulty":"intermediate","explanation":"Cool peripheries with oliguria suggest reduced cardiac output and end-organ hypoperfusion.","reference_text":"2021 ESC Heart Failure Guidelines","reference_url":"https://www.escardio.org/topics/heart-failure/","dr_corazon_hint":"Congestion is 'wet'; hypoperfusion is 'cold'. Look for poor organ blood flow rather than fluid accumulation.","display_order":12,"options":[{"key":"A","text":"Cool extremities and oliguria","correct":true},{"key":"B","text":"Bilateral ankle oedema","correct":false},{"key":"C","text":"Raised JVP","correct":false},{"key":"D","text":"Bibasal crackles","correct":false}]},
  {"module_id":"basic-heart-failure","external_id":"basic-hf-013","stem":"Which heart sound may be associated with volume overload and systolic heart failure?","clinical_scenario":null,"topic":"Symptoms and signs","subtopic":"Examination","difficulty":"foundation","explanation":"A third heart sound (S3) may occur with rapid ventricular filling and volume overload.","reference_text":"2021 ESC Heart Failure Guidelines","reference_url":"https://www.escardio.org/topics/heart-failure/","dr_corazon_hint":"Think of the low-pitched extra sound heard just after S2 during rapid filling.","display_order":13,"options":[{"key":"A","text":"Third heart sound","correct":true},{"key":"B","text":"Opening snap in every case","correct":false},{"key":"C","text":"Fixed split S2 in every case","correct":false},{"key":"D","text":"Pericardial knock as the defining sign","correct":false}]},
  {"module_id":"basic-heart-failure","external_id":"basic-hf-014","stem":"Which initial test should be performed in nearly every patient with suspected heart failure to assess rhythm and electrical abnormalities?","clinical_scenario":null,"topic":"Diagnosis","subtopic":"ECG","difficulty":"foundation","explanation":"A 12-lead ECG is part of the initial assessment and may reveal ischaemia, prior infarction, hypertrophy, conduction disease or arrhythmia.","reference_text":"2021 ESC Heart Failure Guidelines","reference_url":"https://www.escardio.org/topics/heart-failure/","dr_corazon_hint":"This quick bedside test does not confirm HF alone, but a completely normal result makes significant cardiac dysfunction less likely.","display_order":14,"options":[{"key":"A","text":"12-lead ECG","correct":true},{"key":"B","text":"Colonoscopy","correct":false},{"key":"C","text":"EEG","correct":false},{"key":"D","text":"Bone scan","correct":false}]},
  {"module_id":"basic-heart-failure","external_id":"basic-hf-015","stem":"What is the main diagnostic value of a low natriuretic peptide concentration in a patient with suspected heart failure?","clinical_scenario":null,"topic":"Diagnosis","subtopic":"Natriuretic peptides","difficulty":"intermediate","explanation":"A low BNP or NT-proBNP makes heart failure less likely, particularly in a non-acute setting, although clinical context matters.","reference_text":"2021 ESC Heart Failure Guidelines","reference_url":"https://www.escardio.org/topics/heart-failure/","dr_corazon_hint":"Natriuretic peptides are especially useful as rule-out tests; high values have several non-HF causes.","display_order":15,"options":[{"key":"A","text":"It makes heart failure less likely","correct":true},{"key":"B","text":"It proves severe HFrEF","correct":false},{"key":"C","text":"It proves acute myocardial infarction","correct":false},{"key":"D","text":"It identifies the exact valve lesion","correct":false}]},
  {"module_id":"basic-heart-failure","external_id":"basic-hf-016","stem":"Which condition can raise natriuretic peptide levels even without acute heart failure?","clinical_scenario":null,"topic":"Diagnosis","subtopic":"Natriuretic peptides","difficulty":"intermediate","explanation":"Atrial fibrillation and renal dysfunction can raise BNP or NT-proBNP; results must be interpreted clinically.","reference_text":"2021 ESC Heart Failure Guidelines","reference_url":"https://www.escardio.org/topics/heart-failure/","dr_corazon_hint":"Choose a common rhythm disorder that stretches the atria and often increases natriuretic peptide concentrations.","display_order":16,"options":[{"key":"A","text":"Atrial fibrillation","correct":true},{"key":"B","text":"Simple myopia","correct":false},{"key":"C","text":"Healed skin abrasion","correct":false},{"key":"D","text":"Cerumen impaction","correct":false}]},
  {"module_id":"basic-heart-failure","external_id":"basic-hf-017","stem":"Which test best assesses LVEF, chamber size and valve function in suspected heart failure?","clinical_scenario":null,"topic":"Diagnosis","subtopic":"Echocardiography","difficulty":"foundation","explanation":"Transthoracic echocardiography is the principal imaging test for cardiac structure and function in suspected HF.","reference_text":"2021 ESC Heart Failure Guidelines","reference_url":"https://www.escardio.org/topics/heart-failure/","dr_corazon_hint":"Choose the non-invasive cardiac ultrasound that directly evaluates ventricular and valvular function.","display_order":17,"options":[{"key":"A","text":"Transthoracic echocardiography","correct":true},{"key":"B","text":"Abdominal ultrasound","correct":false},{"key":"C","text":"Spirometry alone","correct":false},{"key":"D","text":"Skull radiography","correct":false}]},
  {"module_id":"basic-heart-failure","external_id":"basic-hf-018","stem":"Which chest X-ray finding supports pulmonary venous congestion?","clinical_scenario":null,"topic":"Diagnosis","subtopic":"Chest X-ray","difficulty":"foundation","explanation":"Upper-lobe venous diversion, interstitial oedema, Kerley B lines and alveolar oedema may support congestion.","reference_text":"2021 ESC Heart Failure Guidelines","reference_url":"https://www.escardio.org/topics/heart-failure/","dr_corazon_hint":"Look for a sign of raised pulmonary venous pressure rather than hyperinflation or a focal bone lesion.","display_order":18,"options":[{"key":"A","text":"Kerley B lines","correct":true},{"key":"B","text":"Free subdiaphragmatic air","correct":false},{"key":"C","text":"Hyperinflation alone","correct":false},{"key":"D","text":"Isolated rib fracture","correct":false}]},
  {"module_id":"basic-heart-failure","external_id":"basic-hf-019","stem":"Which laboratory test is essential before and after starting an ACE inhibitor or MRA?","clinical_scenario":null,"topic":"Diagnosis","subtopic":"Monitoring","difficulty":"foundation","explanation":"Renal function and serum potassium should be checked because these medicines can worsen renal function or cause hyperkalaemia.","reference_text":"2021 ESC Heart Failure Guidelines","reference_url":"https://www.escardio.org/topics/heart-failure/","dr_corazon_hint":"Think of the organ and electrolyte most affected by renin–angiotensin–aldosterone system blockade.","display_order":19,"options":[{"key":"A","text":"Creatinine/eGFR and potassium","correct":true},{"key":"B","text":"Amylase only","correct":false},{"key":"C","text":"Uric acid only","correct":false},{"key":"D","text":"Bilirubin only","correct":false}]},
  {"module_id":"basic-heart-failure","external_id":"basic-hf-020","stem":"A patient has breathlessness, ankle oedema and an LVEF of 30%. Which additional step is important when determining the cause?","clinical_scenario":"A 64-year-old patient has newly diagnosed HFrEF and exertional chest pressure.","topic":"Diagnosis","subtopic":"Aetiology","difficulty":"intermediate","explanation":"Possible ischaemic heart disease should be evaluated because it is a common, potentially treatable cause of HFrEF.","reference_text":"2021 ESC Heart Failure Guidelines","reference_url":"https://www.escardio.org/topics/heart-failure/","dr_corazon_hint":"Do not stop after confirming low EF; search for a reversible cause suggested by the chest pressure.","display_order":20,"options":[{"key":"A","text":"Assess for coronary artery disease","correct":true},{"key":"B","text":"Assume idiopathic cardiomyopathy immediately","correct":false},{"key":"C","text":"Repeat only the ankle examination","correct":false},{"key":"D","text":"Avoid taking a family history","correct":false}]},
  {"module_id":"basic-heart-failure","external_id":"basic-hf-021","stem":"Which medicine is primarily used to relieve congestion and oedema in heart failure?","clinical_scenario":null,"topic":"Treatment","subtopic":"Diuretics","difficulty":"foundation","explanation":"Loop diuretics such as furosemide relieve congestion and symptoms by promoting sodium and water excretion.","reference_text":"2021 ESC Heart Failure Guidelines","reference_url":"https://www.escardio.org/topics/heart-failure/","dr_corazon_hint":"Choose the drug class that rapidly removes excess sodium and water; it improves symptoms more than long-term survival.","display_order":21,"options":[{"key":"A","text":"Loop diuretic","correct":true},{"key":"B","text":"Proton-pump inhibitor","correct":false},{"key":"C","text":"Antihistamine","correct":false},{"key":"D","text":"Topical steroid","correct":false}]},
  {"module_id":"basic-heart-failure","external_id":"basic-hf-022","stem":"Which group lists the four foundational disease-modifying drug classes for most suitable patients with HFrEF?","clinical_scenario":null,"topic":"Treatment","subtopic":"Foundational therapy","difficulty":"intermediate","explanation":"Foundational HFrEF therapy includes RAAS inhibition with ACE inhibitor/ARNI, an evidence-based beta-blocker, an MRA and an SGLT2 inhibitor.","reference_text":"2021 ESC Heart Failure Guidelines and 2023 Focused Update","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/focused-update-on-heart-failure/","dr_corazon_hint":"Think of the four pillars: RAAS/ARNI, beta-blocker, MRA and SGLT2 inhibition.","display_order":22,"options":[{"key":"A","text":"ACE inhibitor/ARNI, beta-blocker, MRA and SGLT2 inhibitor","correct":true},{"key":"B","text":"Aspirin, antibiotic, nitrate and calcium supplement","correct":false},{"key":"C","text":"Loop diuretic, NSAID, steroid and digoxin","correct":false},{"key":"D","text":"Warfarin, statin, fibrate and thiazide for every patient","correct":false}]},
  {"module_id":"basic-heart-failure","external_id":"basic-hf-023","stem":"Which beta-blocker is evidence-based for HFrEF?","clinical_scenario":null,"topic":"Treatment","subtopic":"Beta-blockers","difficulty":"foundation","explanation":"Bisoprolol, carvedilol and sustained-release metoprolol succinate are evidence-based beta-blockers for HFrEF.","reference_text":"2021 ESC Heart Failure Guidelines","reference_url":"https://www.escardio.org/topics/heart-failure/","dr_corazon_hint":"Not every beta-blocker has the same outcome evidence; choose one of the classic HFrEF agents.","display_order":23,"options":[{"key":"A","text":"Bisoprolol","correct":true},{"key":"B","text":"Sotalol for every patient","correct":false},{"key":"C","text":"Propranolol as universal first choice","correct":false},{"key":"D","text":"Esmolol as chronic oral therapy","correct":false}]},
  {"module_id":"basic-heart-failure","external_id":"basic-hf-024","stem":"When should initiation or up-titration of a beta-blocker generally be avoided?","clinical_scenario":"A patient with HFrEF is hypotensive, cold and has severe pulmonary oedema.","topic":"Treatment","subtopic":"Beta-blocker safety","difficulty":"intermediate","explanation":"Beta-blocker initiation or escalation should be avoided during shock or severe unstable decompensation; stabilize congestion and perfusion first.","reference_text":"2021 ESC Heart Failure Guidelines","reference_url":"https://www.escardio.org/topics/heart-failure/","dr_corazon_hint":"Beta-blockers help chronic stable HFrEF, but negative inotropy is dangerous in a cold, shocked patient.","display_order":24,"options":[{"key":"A","text":"During cardiogenic shock or severe unstable congestion","correct":true},{"key":"B","text":"Whenever the patient is clinically stable","correct":false},{"key":"C","text":"Because LVEF is 35%","correct":false},{"key":"D","text":"Because the patient is taking a diuretic","correct":false}]},
  {"module_id":"basic-heart-failure","external_id":"basic-hf-025","stem":"Which adverse effect requires particular monitoring with spironolactone?","clinical_scenario":null,"topic":"Treatment","subtopic":"MRA","difficulty":"foundation","explanation":"Spironolactone can cause hyperkalaemia and worsening renal function; potassium and renal function require monitoring.","reference_text":"2021 ESC Heart Failure Guidelines","reference_url":"https://www.escardio.org/topics/heart-failure/","dr_corazon_hint":"This aldosterone antagonist retains potassium; think of the electrolyte that can become dangerously high.","display_order":25,"options":[{"key":"A","text":"Hyperkalaemia","correct":true},{"key":"B","text":"Severe hypocalcaemia as the usual effect","correct":false},{"key":"C","text":"Profound neutropenia in most patients","correct":false},{"key":"D","text":"Hypernatraemia in every patient","correct":false}]},
  {"module_id":"basic-heart-failure","external_id":"basic-hf-026","stem":"Which statement about SGLT2 inhibitors in heart failure is most accurate?","clinical_scenario":null,"topic":"Treatment","subtopic":"SGLT2 inhibitors","difficulty":"intermediate","explanation":"SGLT2 inhibitors improve HF outcomes in patients with and without diabetes and across a broad range of LVEF.","reference_text":"2023 ESC Focused Update on Heart Failure","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/focused-update-on-heart-failure/","dr_corazon_hint":"Do not let the drug name restrict your thinking to diabetes; the benefit extends to heart failure itself.","display_order":26,"options":[{"key":"A","text":"They may benefit heart failure even without diabetes","correct":true},{"key":"B","text":"They are used only for type 1 diabetes","correct":false},{"key":"C","text":"They replace all other HFrEF therapy","correct":false},{"key":"D","text":"They are loop diuretics","correct":false}]},
  {"module_id":"basic-heart-failure","external_id":"basic-hf-027","stem":"Which medicine class can worsen fluid retention and renal function in heart failure and should generally be avoided where possible?","clinical_scenario":null,"topic":"Treatment","subtopic":"Avoidance","difficulty":"foundation","explanation":"NSAIDs can cause sodium retention, raise blood pressure and worsen kidney function, precipitating decompensation.","reference_text":"2021 ESC Heart Failure Guidelines","reference_url":"https://www.escardio.org/topics/heart-failure/","dr_corazon_hint":"Think of common over-the-counter painkillers that inhibit renal prostaglandins and retain sodium.","display_order":27,"options":[{"key":"A","text":"NSAIDs","correct":true},{"key":"B","text":"SGLT2 inhibitors","correct":false},{"key":"C","text":"ACE inhibitors in every circumstance","correct":false},{"key":"D","text":"Evidence-based beta-blockers in stable HFrEF","correct":false}]},
  {"module_id":"basic-heart-failure","external_id":"basic-hf-028","stem":"A patient with acute pulmonary oedema has oxygen saturation 84%. Which immediate supportive treatment is appropriate?","clinical_scenario":"The patient is severely breathless with diffuse crackles and marked hypoxaemia.","topic":"Treatment","subtopic":"Acute heart failure","difficulty":"foundation","explanation":"Oxygen is appropriate for hypoxaemia. Routine oxygen is not required when saturation is normal.","reference_text":"2021 ESC Heart Failure Guidelines","reference_url":"https://www.escardio.org/topics/heart-failure/","dr_corazon_hint":"The saturation is the decisive clue: oxygen treats hypoxaemia, not the diagnosis label alone.","display_order":28,"options":[{"key":"A","text":"Administer oxygen and urgently assess ventilation needs","correct":true},{"key":"B","text":"Withhold oxygen because it is never used in HF","correct":false},{"key":"C","text":"Give large-volume IV saline","correct":false},{"key":"D","text":"Delay monitoring until after a chest X-ray","correct":false}]},
  {"module_id":"basic-heart-failure","external_id":"basic-hf-029","stem":"Which patient with heart failure most urgently requires emergency escalation?","clinical_scenario":null,"topic":"Symptoms and signs","subtopic":"Red flags","difficulty":"foundation","explanation":"Hypotension, confusion and cool peripheries suggest cardiogenic shock and require immediate escalation.","reference_text":"2021 ESC Heart Failure Guidelines","reference_url":"https://www.escardio.org/topics/heart-failure/","dr_corazon_hint":"Prioritize perfusion and consciousness; shock is more urgent than stable mild ankle swelling.","display_order":29,"options":[{"key":"A","text":"A confused patient with BP 75/45 mmHg and cool limbs","correct":true},{"key":"B","text":"A stable patient with mild chronic ankle oedema","correct":false},{"key":"C","text":"An asymptomatic patient requesting a routine refill","correct":false},{"key":"D","text":"A stable patient walking comfortably to clinic","correct":false}]},
  {"module_id":"basic-heart-failure","external_id":"basic-hf-030","stem":"What is the main purpose of an ICD in selected patients with HFrEF?","clinical_scenario":null,"topic":"Treatment","subtopic":"Devices","difficulty":"intermediate","explanation":"An ICD detects and terminates life-threatening ventricular arrhythmias to reduce sudden cardiac death risk in selected patients.","reference_text":"2021 ESC Heart Failure Guidelines","reference_url":"https://www.escardio.org/topics/heart-failure/","dr_corazon_hint":"An ICD is an anti-arrhythmic safety device; it does not directly improve congestion.","display_order":30,"options":[{"key":"A","text":"Prevent sudden death from ventricular tachyarrhythmia","correct":true},{"key":"B","text":"Remove excess fluid","correct":false},{"key":"C","text":"Replace the mitral valve","correct":false},{"key":"D","text":"Measure natriuretic peptides","correct":false}]},
  {"module_id":"basic-heart-failure","external_id":"basic-hf-031","stem":"What is the principal aim of cardiac resynchronization therapy in an appropriately selected patient?","clinical_scenario":null,"topic":"Treatment","subtopic":"Devices","difficulty":"intermediate","explanation":"CRT coordinates ventricular contraction in selected patients with electrical dyssynchrony, improving function and outcomes.","reference_text":"2021 ESC Heart Failure Guidelines","reference_url":"https://www.escardio.org/topics/heart-failure/","dr_corazon_hint":"Think of a wide QRS and uncoordinated ventricular activation; the therapy aims to resynchronize contraction.","display_order":31,"options":[{"key":"A","text":"Improve ventricular synchrony","correct":true},{"key":"B","text":"Dissolve a coronary thrombus","correct":false},{"key":"C","text":"Directly lower LDL cholesterol","correct":false},{"key":"D","text":"Drain a pericardial effusion","correct":false}]},
  {"module_id":"basic-heart-failure","external_id":"basic-hf-032","stem":"Which statement about daily weight monitoring is most appropriate when counselling a patient with heart failure?","clinical_scenario":null,"topic":"Counselling","subtopic":"Self-monitoring","difficulty":"foundation","explanation":"A rapid weight increase may reflect fluid retention and should prompt contact according to the agreed care plan.","reference_text":"2021 ESC Heart Failure Guidelines","reference_url":"https://www.escardio.org/topics/heart-failure/","dr_corazon_hint":"The useful change is rapid and unexpected, not ordinary long-term variation.","display_order":32,"options":[{"key":"A","text":"Rapid weight gain may warn of fluid retention","correct":true},{"key":"B","text":"Weight has no relationship to congestion","correct":false},{"key":"C","text":"The patient should stop all medicines after any gain","correct":false},{"key":"D","text":"Weight should be checked only once a year","correct":false}]},
  {"module_id":"basic-heart-failure","external_id":"basic-hf-033","stem":"Which advice about prescribed heart failure medicines is safest?","clinical_scenario":null,"topic":"Counselling","subtopic":"Adherence","difficulty":"foundation","explanation":"Patients should understand each medicine and seek advice rather than stopping disease-modifying treatment abruptly.","reference_text":"NICE Shared Decision Making and ESC Heart Failure guidance","reference_url":"https://www.nice.org.uk/guidance/ng197","dr_corazon_hint":"The best counselling balances adherence with safety: do not encourage unsupervised abrupt discontinuation.","display_order":33,"options":[{"key":"A","text":"Do not stop medicines abruptly without clinical advice","correct":true},{"key":"B","text":"Stop all treatment as soon as symptoms improve","correct":false},{"key":"C","text":"Double every dose after one missed tablet","correct":false},{"key":"D","text":"Share medicines with relatives who have breathlessness","correct":false}]},
  {"module_id":"basic-heart-failure","external_id":"basic-hf-034","stem":"Which symptom should a patient with heart failure be told to treat as an emergency?","clinical_scenario":null,"topic":"Counselling","subtopic":"Safety net","difficulty":"foundation","explanation":"Severe breathlessness at rest with blue lips suggests life-threatening hypoxaemia or pulmonary oedema and requires emergency care.","reference_text":"ESC Heart Failure patient-centred care principles","reference_url":"https://www.escardio.org/topics/heart-failure/","dr_corazon_hint":"Choose the symptom indicating immediate respiratory compromise, not a stable chronic limitation.","display_order":34,"options":[{"key":"A","text":"Severe breathlessness at rest with blue lips","correct":true},{"key":"B","text":"Stable mild fatigue after a long day","correct":false},{"key":"C","text":"A single hiccup","correct":false},{"key":"D","text":"Mild thirst after exercise","correct":false}]},
  {"module_id":"basic-heart-failure","external_id":"basic-hf-035","stem":"Which lifestyle recommendation is appropriate for a clinically stable patient with chronic heart failure?","clinical_scenario":null,"topic":"Counselling","subtopic":"Exercise","difficulty":"foundation","explanation":"Regular individualized physical activity and cardiac rehabilitation improve functional capacity and support self-care in stable HF.","reference_text":"2021 ESC Heart Failure Guidelines","reference_url":"https://www.escardio.org/topics/heart-failure/","dr_corazon_hint":"Stable HF is not a reason for permanent bed rest; activity should be individualized and progressive.","display_order":35,"options":[{"key":"A","text":"Participate in individualized regular activity or cardiac rehabilitation","correct":true},{"key":"B","text":"Remain on permanent bed rest","correct":false},{"key":"C","text":"Start maximal exercise without assessment","correct":false},{"key":"D","text":"Avoid all walking forever","correct":false}]},
  {"module_id":"basic-heart-failure","external_id":"basic-hf-036","stem":"Why should iron status be assessed in heart failure?","clinical_scenario":null,"topic":"Diagnosis","subtopic":"Comorbidity","difficulty":"intermediate","explanation":"Iron deficiency is common in HF, contributes to exercise intolerance and may be treatable in selected patients.","reference_text":"2021 ESC Heart Failure Guidelines and 2023 Focused Update","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/focused-update-on-heart-failure/","dr_corazon_hint":"The clue is reduced exercise capacity even when haemoglobin may not be profoundly low.","display_order":36,"options":[{"key":"A","text":"Iron deficiency is common and may worsen symptoms","correct":true},{"key":"B","text":"Iron overload is present in every patient","correct":false},{"key":"C","text":"Ferritin directly measures ejection fraction","correct":false},{"key":"D","text":"Iron status replaces echocardiography","correct":false}]},
  {"module_id":"basic-heart-failure","external_id":"basic-hf-037","stem":"A patient with HFpEF has hypertension, obesity and atrial fibrillation. Which management principle is most appropriate?","clinical_scenario":null,"topic":"Treatment","subtopic":"HFpEF","difficulty":"intermediate","explanation":"HFpEF care includes treating congestion and aggressively managing comorbidities and risk factors; SGLT2 inhibitors may also improve outcomes.","reference_text":"2023 ESC Focused Update on Heart Failure","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/focused-update-on-heart-failure/","dr_corazon_hint":"HFpEF management is not 'no treatment'; address fluid overload and the conditions driving high filling pressures.","display_order":37,"options":[{"key":"A","text":"Treat congestion and optimize hypertension, obesity and AF","correct":true},{"key":"B","text":"Ignore comorbidities because EF is preserved","correct":false},{"key":"C","text":"Give routine long-term NSAIDs","correct":false},{"key":"D","text":"Stop all antihypertensive therapy","correct":false}]},
  {"module_id":"basic-heart-failure","external_id":"basic-hf-038","stem":"Which finding best distinguishes right-sided congestion?","clinical_scenario":null,"topic":"Symptoms and signs","subtopic":"Right heart failure","difficulty":"foundation","explanation":"Hepatomegaly, ascites, oedema and raised JVP suggest systemic venous congestion from right-sided failure.","reference_text":"2021 ESC Heart Failure Guidelines","reference_url":"https://www.escardio.org/topics/heart-failure/","dr_corazon_hint":"Think below the diaphragm and in the systemic veins rather than only the lungs.","display_order":38,"options":[{"key":"A","text":"Ascites with raised JVP","correct":true},{"key":"B","text":"Isolated wheeze after allergen exposure","correct":false},{"key":"C","text":"Photophobia and neck stiffness","correct":false},{"key":"D","text":"Unilateral conjunctivitis","correct":false}]},
  {"module_id":"basic-heart-failure","external_id":"basic-hf-039","stem":"A patient with acute heart failure is warm with marked oedema and raised JVP. Which haemodynamic description fits best?","clinical_scenario":null,"topic":"Symptoms and signs","subtopic":"Clinical profile","difficulty":"advanced","explanation":"Warm and wet describes adequate peripheral perfusion with clinical congestion.","reference_text":"2021 ESC Heart Failure Guidelines","reference_url":"https://www.escardio.org/topics/heart-failure/","dr_corazon_hint":"Translate the bedside words: warm equals perfused; wet equals congested.","display_order":39,"options":[{"key":"A","text":"Warm and wet","correct":true},{"key":"B","text":"Cold and dry","correct":false},{"key":"C","text":"Warm and dry","correct":false},{"key":"D","text":"Cold and wet","correct":false}]},
  {"module_id":"basic-heart-failure","external_id":"basic-hf-040","stem":"A patient with acute heart failure is hypotensive, cool and has raised JVP. Which profile is most concerning?","clinical_scenario":null,"topic":"Symptoms and signs","subtopic":"Clinical profile","difficulty":"advanced","explanation":"Cold and wet indicates both hypoperfusion and congestion and carries high risk.","reference_text":"2021 ESC Heart Failure Guidelines","reference_url":"https://www.escardio.org/topics/heart-failure/","dr_corazon_hint":"Combine the signs: cool and hypotensive means cold; raised JVP means wet.","display_order":40,"options":[{"key":"A","text":"Cold and wet","correct":true},{"key":"B","text":"Warm and dry","correct":false},{"key":"C","text":"Warm and wet","correct":false},{"key":"D","text":"Cold and dry only","correct":false}]},
  {"module_id":"basic-heart-failure","external_id":"basic-hf-041","stem":"Which is the best way to explain an ACE inhibitor to a patient with HFrEF?","clinical_scenario":null,"topic":"Counselling","subtopic":"Medication purpose","difficulty":"foundation","explanation":"ACE inhibitors reduce harmful neurohormonal activation, improve outcomes and require monitoring of blood pressure, renal function and potassium.","reference_text":"2021 ESC Heart Failure Guidelines","reference_url":"https://www.escardio.org/topics/heart-failure/","dr_corazon_hint":"Explain both benefit and monitoring; avoid promising that it simply 'removes water'.","display_order":41,"options":[{"key":"A","text":"It helps the heart work against less harmful hormonal stress and can improve outcomes","correct":true},{"key":"B","text":"It is only a painkiller","correct":false},{"key":"C","text":"It cures every cause immediately","correct":false},{"key":"D","text":"It requires no blood tests","correct":false}]},
  {"module_id":"basic-heart-failure","external_id":"basic-hf-042","stem":"A patient develops a persistent dry cough after starting an ACE inhibitor. Which alternative class may be considered when appropriate?","clinical_scenario":null,"topic":"Treatment","subtopic":"RAAS inhibition","difficulty":"intermediate","explanation":"An ARB may be used when ACE inhibitor cough is troublesome and an ARNI is not the chosen alternative; therapy depends on the clinical plan.","reference_text":"2021 ESC Heart Failure Guidelines","reference_url":"https://www.escardio.org/topics/heart-failure/","dr_corazon_hint":"The cough is related to bradykinin; choose a renin–angiotensin blocker that does not inhibit ACE.","display_order":42,"options":[{"key":"A","text":"An angiotensin receptor blocker","correct":true},{"key":"B","text":"A long-term NSAID","correct":false},{"key":"C","text":"A sedating antihistamine as the sole solution","correct":false},{"key":"D","text":"Stop all HF therapy permanently","correct":false}]},
  {"module_id":"basic-heart-failure","external_id":"basic-hf-043","stem":"Which patient is most likely to have a falsely lower natriuretic peptide concentration?","clinical_scenario":null,"topic":"Diagnosis","subtopic":"Natriuretic peptides","difficulty":"advanced","explanation":"Obesity is associated with lower natriuretic peptide concentrations, so a relatively low value needs careful interpretation.","reference_text":"2021 ESC Heart Failure Guidelines","reference_url":"https://www.escardio.org/topics/heart-failure/","dr_corazon_hint":"One common metabolic condition suppresses peptide levels despite genuine HF.","display_order":43,"options":[{"key":"A","text":"A patient with obesity","correct":true},{"key":"B","text":"A patient with atrial fibrillation","correct":false},{"key":"C","text":"A patient with advanced age","correct":false},{"key":"D","text":"A patient with renal dysfunction","correct":false}]},
  {"module_id":"basic-heart-failure","external_id":"basic-hf-044","stem":"Which finding makes heart failure less likely in an untreated patient with chronic breathlessness?","clinical_scenario":null,"topic":"Diagnosis","subtopic":"Probability","difficulty":"intermediate","explanation":"A normal ECG and low natriuretic peptide both reduce the probability of HF, although neither replaces clinical judgment.","reference_text":"2021 ESC Heart Failure Guidelines","reference_url":"https://www.escardio.org/topics/heart-failure/","dr_corazon_hint":"Choose the combination with strong rule-out value rather than nonspecific symptoms.","display_order":44,"options":[{"key":"A","text":"Normal ECG with low natriuretic peptide","correct":true},{"key":"B","text":"Raised JVP with pulmonary oedema","correct":false},{"key":"C","text":"Third heart sound with displaced apex","correct":false},{"key":"D","text":"Reduced LVEF on echocardiography","correct":false}]},
  {"module_id":"basic-heart-failure","external_id":"basic-hf-045","stem":"Which action best applies shared decision making in heart failure?","clinical_scenario":null,"topic":"Counselling","subtopic":"Shared decisions","difficulty":"foundation","explanation":"Shared decision making combines evidence with the patient’s goals, preferences and circumstances and checks understanding.","reference_text":"NICE Shared Decision Making NG197","reference_url":"https://www.nice.org.uk/guidance/ng197","dr_corazon_hint":"The patient is a partner, not a passive recipient; look for options, preferences and teach-back.","display_order":45,"options":[{"key":"A","text":"Explain options and invite the patient’s goals and preferences","correct":true},{"key":"B","text":"Use unexplained jargon and make every decision alone","correct":false},{"key":"C","text":"Avoid discussing adverse effects","correct":false},{"key":"D","text":"Give no written plan","correct":false}]},
  {"module_id":"basic-heart-failure","external_id":"basic-hf-046","stem":"Which vaccination discussion is appropriate in chronic heart failure?","clinical_scenario":null,"topic":"Counselling","subtopic":"Prevention","difficulty":"foundation","explanation":"Influenza and pneumococcal vaccination should be considered according to local recommendations because respiratory infection can precipitate decompensation.","reference_text":"2021 ESC Heart Failure Guidelines","reference_url":"https://www.escardio.org/topics/heart-failure/","dr_corazon_hint":"Respiratory infections are common triggers; prevention is part of comprehensive HF care.","display_order":46,"options":[{"key":"A","text":"Discuss influenza and pneumococcal vaccination according to local guidance","correct":true},{"key":"B","text":"Vaccination is always contraindicated in HF","correct":false},{"key":"C","text":"Only travel vaccines matter","correct":false},{"key":"D","text":"Vaccines replace HF medicines","correct":false}]},
  {"module_id":"basic-heart-failure","external_id":"basic-hf-047","stem":"A patient with HFrEF feels better after diuresis. Why should disease-modifying therapy still be optimized?","clinical_scenario":null,"topic":"Treatment","subtopic":"Outcomes","difficulty":"intermediate","explanation":"Relief of congestion does not correct the disease process; disease-modifying therapies reduce hospitalization and mortality.","reference_text":"2021 ESC Heart Failure Guidelines","reference_url":"https://www.escardio.org/topics/heart-failure/","dr_corazon_hint":"Separate symptom relief from prognosis: a dry patient can still remain at high long-term risk.","display_order":47,"options":[{"key":"A","text":"Because symptom relief does not remove long-term risk","correct":true},{"key":"B","text":"Because loop diuretics always cure cardiomyopathy","correct":false},{"key":"C","text":"Because all patients need antibiotics","correct":false},{"key":"D","text":"Because EF is irrelevant to follow-up","correct":false}]},
  {"module_id":"basic-heart-failure","external_id":"basic-hf-048","stem":"Which follow-up finding should prompt review of diuretic dose and renal function?","clinical_scenario":"A patient recently discharged after congestion now reports dizziness, poor intake and a 4-kg weight loss in one week.","topic":"Treatment","subtopic":"Monitoring","difficulty":"advanced","explanation":"Rapid weight loss with dizziness and poor intake may indicate over-diuresis, hypotension or renal dysfunction and needs prompt review.","reference_text":"2021 ESC Heart Failure Guidelines","reference_url":"https://www.escardio.org/topics/heart-failure/","dr_corazon_hint":"Too much fluid removal can be harmful; the combination of rapid loss and dizziness is the trap.","display_order":48,"options":[{"key":"A","text":"Assess volume status, blood pressure, renal function and diuretic dose","correct":true},{"key":"B","text":"Automatically double the diuretic","correct":false},{"key":"C","text":"Ignore the symptoms for one month","correct":false},{"key":"D","text":"Advise unrestricted NSAID use","correct":false}]},
  {"module_id":"basic-heart-failure","external_id":"basic-hf-049","stem":"Which statement best explains why an echocardiogram should assess valves in heart failure?","clinical_scenario":null,"topic":"Diagnosis","subtopic":"Valvular disease","difficulty":"intermediate","explanation":"Severe valve disease can cause or worsen HF and may require specific intervention beyond medical treatment.","reference_text":"2021 ESC Heart Failure Guidelines","reference_url":"https://www.escardio.org/topics/heart-failure/","dr_corazon_hint":"A valve lesion may be the cause, not merely a consequence; finding it can change definitive management.","display_order":49,"options":[{"key":"A","text":"Valve disease may be a treatable cause of heart failure","correct":true},{"key":"B","text":"Valves never affect ventricular loading","correct":false},{"key":"C","text":"Valve assessment replaces all blood tests","correct":false},{"key":"D","text":"Only congenital patients need valve imaging","correct":false}]},
  {"module_id":"basic-heart-failure","external_id":"basic-hf-050","stem":"A patient asks what to do if breathlessness and ankle swelling worsen over two days. What is the best response?","clinical_scenario":null,"topic":"Counselling","subtopic":"Action plan","difficulty":"intermediate","explanation":"Worsening symptoms and swelling may indicate congestion; the patient should follow the agreed action plan and contact the HF team promptly, with emergency care for severe symptoms.","reference_text":"ESC Heart Failure patient-centred care principles","reference_url":"https://www.escardio.org/topics/heart-failure/","dr_corazon_hint":"Give an actionable safety net: early contact for deterioration and emergency help for severe breathlessness or instability.","display_order":50,"options":[{"key":"A","text":"Follow the action plan and contact the heart-failure team promptly","correct":true},{"key":"B","text":"Stop every medicine and wait a week","correct":false},{"key":"C","text":"Take a relative’s medication","correct":false},{"key":"D","text":"Ignore swelling unless pain develops","correct":false}]}
]
$questions$::jsonb) as x(
  module_id text, external_id text, stem text, clinical_scenario text,
  topic text, subtopic text, difficulty text, explanation text,
  reference_text text, reference_url text, dr_corazon_hint text,
  display_order integer, options jsonb
);

-- Atrial Fibrillation: 50 questions
insert into acl_basic_question_seed
select * from jsonb_to_recordset($questions$
[
  {"module_id":"basic-atrial-fibrillation","external_id":"basic-af-001","stem":"Which ECG description is characteristic of atrial fibrillation?","clinical_scenario":null,"topic":"Definition","subtopic":"ECG features","difficulty":"foundation","explanation":"AF is characterized by irregular RR intervals and absence of discrete, consistent P waves.","reference_text":"2024 ESC Atrial Fibrillation Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/atrial-fibrillation/","dr_corazon_hint":"Use both clues together: the rhythm is irregularly irregular and organized P waves are absent.","display_order":1,"options":[{"key":"A","text":"Regular RR intervals with saw-tooth waves","correct":false},{"key":"B","text":"Irregular RR intervals with no discrete P waves","correct":true},{"key":"C","text":"Progressive PR prolongation","correct":false},{"key":"D","text":"Regular narrow-complex rhythm with one P before every QRS","correct":false}]},
  {"module_id":"basic-atrial-fibrillation","external_id":"basic-af-002","stem":"Which best defines paroxysmal atrial fibrillation?","clinical_scenario":null,"topic":"Definition","subtopic":"Classification","difficulty":"foundation","explanation":"Paroxysmal AF terminates spontaneously or with intervention within seven days of onset.","reference_text":"2024 ESC Atrial Fibrillation Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/atrial-fibrillation/","dr_corazon_hint":"The key is termination within seven days, not whether the patient felt symptoms.","display_order":2,"options":[{"key":"A","text":"AF that terminates within seven days","correct":true},{"key":"B","text":"AF accepted permanently by patient and clinician","correct":false},{"key":"C","text":"AF lasting at least twelve months in every case","correct":false},{"key":"D","text":"Any regular tachycardia","correct":false}]},
  {"module_id":"basic-atrial-fibrillation","external_id":"basic-af-003","stem":"What does permanent atrial fibrillation mean?","clinical_scenario":null,"topic":"Definition","subtopic":"Classification","difficulty":"intermediate","explanation":"Permanent AF is a therapeutic attitude: patient and clinician accept AF and do not plan further attempts to restore sinus rhythm.","reference_text":"2024 ESC Atrial Fibrillation Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/atrial-fibrillation/","dr_corazon_hint":"Permanent describes a shared management decision, not an ECG property or a fixed duration alone.","display_order":3,"options":[{"key":"A","text":"AF accepted with no further rhythm-restoration attempts planned","correct":true},{"key":"B","text":"AF present for exactly 48 hours","correct":false},{"key":"C","text":"AF with a ventricular rate below 60","correct":false},{"key":"D","text":"AF that can never be cardioverted","correct":false}]},
  {"module_id":"basic-atrial-fibrillation","external_id":"basic-af-004","stem":"Which is a major modifiable risk factor for atrial fibrillation?","clinical_scenario":null,"topic":"Causes","subtopic":"Risk factors","difficulty":"foundation","explanation":"Hypertension promotes atrial remodeling and is a common modifiable AF risk factor.","reference_text":"2024 ESC Atrial Fibrillation Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/atrial-fibrillation/","dr_corazon_hint":"Choose the common cardiovascular condition that chronically raises atrial pressure and promotes remodeling.","display_order":4,"options":[{"key":"A","text":"Hypertension","correct":true},{"key":"B","text":"Myopia","correct":false},{"key":"C","text":"Appendicectomy","correct":false},{"key":"D","text":"Seasonal rhinitis alone","correct":false}]},
  {"module_id":"basic-atrial-fibrillation","external_id":"basic-af-005","stem":"Which valve lesion is classically associated with atrial fibrillation and markedly enlarged left atrium?","clinical_scenario":null,"topic":"Causes","subtopic":"Valvular disease","difficulty":"foundation","explanation":"Mitral stenosis raises left atrial pressure, causing enlargement and AF.","reference_text":"2024 ESC Atrial Fibrillation Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/atrial-fibrillation/","dr_corazon_hint":"Think of the valve obstruction directly upstream of the left ventricle that loads the left atrium.","display_order":5,"options":[{"key":"A","text":"Mitral stenosis","correct":true},{"key":"B","text":"Mild pulmonary regurgitation","correct":false},{"key":"C","text":"Isolated trivial tricuspid regurgitation","correct":false},{"key":"D","text":"No valve disease is associated with AF","correct":false}]},
  {"module_id":"basic-atrial-fibrillation","external_id":"basic-af-006","stem":"Which endocrine disorder should be considered as a reversible contributor to new atrial fibrillation?","clinical_scenario":null,"topic":"Causes","subtopic":"Thyroid disease","difficulty":"foundation","explanation":"Hyperthyroidism increases adrenergic drive and predisposes to AF.","reference_text":"2024 ESC Atrial Fibrillation Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/atrial-fibrillation/","dr_corazon_hint":"Choose the thyroid state associated with heat intolerance, tremor and tachyarrhythmia.","display_order":6,"options":[{"key":"A","text":"Hyperthyroidism","correct":true},{"key":"B","text":"Stable euthyroidism","correct":false},{"key":"C","text":"Isolated vitamin D deficiency","correct":false},{"key":"D","text":"Simple goitre with normal thyroid function in every case","correct":false}]},
  {"module_id":"basic-atrial-fibrillation","external_id":"basic-af-007","stem":"Which sleep-related condition increases AF risk and recurrence?","clinical_scenario":null,"topic":"Causes","subtopic":"Sleep apnoea","difficulty":"foundation","explanation":"Obstructive sleep apnoea is associated with AF and should be addressed as part of risk-factor management.","reference_text":"2024 ESC Atrial Fibrillation Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/atrial-fibrillation/","dr_corazon_hint":"Snoring, witnessed apnoea and daytime sleepiness point to an important modifiable AF driver.","display_order":7,"options":[{"key":"A","text":"Obstructive sleep apnoea","correct":true},{"key":"B","text":"Sleepwalking","correct":false},{"key":"C","text":"Occasional nightmares","correct":false},{"key":"D","text":"Jet lag alone","correct":false}]},
  {"module_id":"basic-atrial-fibrillation","external_id":"basic-af-008","stem":"Which lifestyle exposure can precipitate atrial fibrillation, particularly after binge use?","clinical_scenario":null,"topic":"Causes","subtopic":"Alcohol","difficulty":"foundation","explanation":"Excess alcohol, especially binge drinking, can trigger AF and increase recurrence.","reference_text":"2024 ESC Atrial Fibrillation Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/atrial-fibrillation/","dr_corazon_hint":"Recall the classic 'holiday heart' association.","display_order":8,"options":[{"key":"A","text":"Excess alcohol","correct":true},{"key":"B","text":"Adequate water intake","correct":false},{"key":"C","text":"A balanced breakfast","correct":false},{"key":"D","text":"Routine vaccination","correct":false}]},
  {"module_id":"basic-atrial-fibrillation","external_id":"basic-af-009","stem":"Which symptom is common in atrial fibrillation?","clinical_scenario":null,"topic":"Symptoms and signs","subtopic":"Presentation","difficulty":"foundation","explanation":"Palpitations are common, although AF may also cause dyspnoea, fatigue, dizziness or no symptoms.","reference_text":"2024 ESC Atrial Fibrillation Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/atrial-fibrillation/","dr_corazon_hint":"Choose the symptom most directly produced by awareness of an irregular heartbeat.","display_order":9,"options":[{"key":"A","text":"Palpitations","correct":true},{"key":"B","text":"Haematuria as the defining symptom","correct":false},{"key":"C","text":"Jaundice in every patient","correct":false},{"key":"D","text":"Photophobia","correct":false}]},
  {"module_id":"basic-atrial-fibrillation","external_id":"basic-af-010","stem":"What pulse finding is classically associated with atrial fibrillation?","clinical_scenario":null,"topic":"Symptoms and signs","subtopic":"Pulse","difficulty":"foundation","explanation":"The pulse in AF is typically irregularly irregular.","reference_text":"2024 ESC Atrial Fibrillation Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/atrial-fibrillation/","dr_corazon_hint":"There is no repeating pattern in the intervals between beats.","display_order":10,"options":[{"key":"A","text":"Irregularly irregular pulse","correct":true},{"key":"B","text":"Perfectly regular pulse in every patient","correct":false},{"key":"C","text":"Pulsus paradoxus as the defining feature","correct":false},{"key":"D","text":"Radio-radial delay in every case","correct":false}]},
  {"module_id":"basic-atrial-fibrillation","external_id":"basic-af-011","stem":"Which presentation indicates haemodynamic instability due to atrial fibrillation?","clinical_scenario":"A patient in AF has severe pulmonary oedema and BP 75/45 mmHg.","topic":"Symptoms and signs","subtopic":"Instability","difficulty":"foundation","explanation":"Hypotension with acute pulmonary oedema indicates instability and requires urgent synchronized cardioversion when AF is causal.","reference_text":"2024 ESC Atrial Fibrillation Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/atrial-fibrillation/","dr_corazon_hint":"Do not focus only on the heart rate; shock and pulmonary oedema are the decisive red flags.","display_order":11,"options":[{"key":"A","text":"Hypotension with acute pulmonary oedema","correct":true},{"key":"B","text":"Mild palpitations with normal blood pressure","correct":false},{"key":"C","text":"Asymptomatic AF found on routine ECG","correct":false},{"key":"D","text":"Stable fatigue for several months","correct":false}]},
  {"module_id":"basic-atrial-fibrillation","external_id":"basic-af-012","stem":"Which complication may be the first presentation of previously unrecognized atrial fibrillation?","clinical_scenario":null,"topic":"Symptoms and signs","subtopic":"Complications","difficulty":"foundation","explanation":"AF can cause left atrial thrombus and embolic ischaemic stroke, sometimes before palpitations are recognized.","reference_text":"2024 ESC Atrial Fibrillation Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/atrial-fibrillation/","dr_corazon_hint":"Think of the most feared thromboembolic complication.","display_order":12,"options":[{"key":"A","text":"Ischaemic stroke","correct":true},{"key":"B","text":"Appendicitis","correct":false},{"key":"C","text":"Cataract","correct":false},{"key":"D","text":"Otitis externa","correct":false}]},
  {"module_id":"basic-atrial-fibrillation","external_id":"basic-af-013","stem":"What is required to establish a clinical diagnosis of atrial fibrillation?","clinical_scenario":null,"topic":"Diagnosis","subtopic":"Documentation","difficulty":"foundation","explanation":"The rhythm should be documented on an ECG tracing of adequate quality and interpreted by a clinician.","reference_text":"2024 ESC Atrial Fibrillation Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/atrial-fibrillation/","dr_corazon_hint":"A pulse alert or smartwatch notification is a prompt for confirmation, not the final diagnosis by itself.","display_order":13,"options":[{"key":"A","text":"ECG documentation of the rhythm","correct":true},{"key":"B","text":"Palpitations alone","correct":false},{"key":"C","text":"A high blood pressure reading alone","correct":false},{"key":"D","text":"Family history alone","correct":false}]},
  {"module_id":"basic-atrial-fibrillation","external_id":"basic-af-014","stem":"A patient reports brief weekly palpitations but has a normal clinic ECG. What is the most useful next diagnostic approach?","clinical_scenario":null,"topic":"Diagnosis","subtopic":"Ambulatory monitoring","difficulty":"intermediate","explanation":"Ambulatory ECG monitoring can correlate intermittent symptoms with rhythm and detect paroxysmal AF.","reference_text":"2024 ESC Atrial Fibrillation Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/atrial-fibrillation/","dr_corazon_hint":"The arrhythmia is intermittent, so extend the recording beyond the clinic visit.","display_order":14,"options":[{"key":"A","text":"Ambulatory ECG monitoring","correct":true},{"key":"B","text":"Repeat chest X-ray every hour","correct":false},{"key":"C","text":"No further assessment because one ECG was normal","correct":false},{"key":"D","text":"Colonoscopy","correct":false}]},
  {"module_id":"basic-atrial-fibrillation","external_id":"basic-af-015","stem":"Which blood test is particularly important in new atrial fibrillation when clinically appropriate?","clinical_scenario":null,"topic":"Diagnosis","subtopic":"Laboratory assessment","difficulty":"foundation","explanation":"Thyroid function should be assessed because hyperthyroidism is a reversible contributor to AF.","reference_text":"2024 ESC Atrial Fibrillation Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/atrial-fibrillation/","dr_corazon_hint":"Look for a reversible endocrine trigger.","display_order":15,"options":[{"key":"A","text":"Thyroid function","correct":true},{"key":"B","text":"Serum amylase only","correct":false},{"key":"C","text":"Tumour markers routinely","correct":false},{"key":"D","text":"No blood tests are ever needed","correct":false}]},
  {"module_id":"basic-atrial-fibrillation","external_id":"basic-af-016","stem":"What is the main role of transthoracic echocardiography in atrial fibrillation?","clinical_scenario":null,"topic":"Diagnosis","subtopic":"Echocardiography","difficulty":"foundation","explanation":"Echo assesses ventricular function, chamber size and structural or valvular heart disease, all of which influence management.","reference_text":"2024 ESC Atrial Fibrillation Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/atrial-fibrillation/","dr_corazon_hint":"The test looks for the substrate and consequences of AF, not just the rhythm itself.","display_order":16,"options":[{"key":"A","text":"Assess ventricular function, chamber size and valve disease","correct":true},{"key":"B","text":"Confirm every episode without an ECG","correct":false},{"key":"C","text":"Measure anticoagulant concentration","correct":false},{"key":"D","text":"Replace renal-function testing","correct":false}]},
  {"module_id":"basic-atrial-fibrillation","external_id":"basic-af-017","stem":"What is the purpose of a thromboembolic risk score in atrial fibrillation?","clinical_scenario":null,"topic":"Diagnosis","subtopic":"Stroke risk","difficulty":"foundation","explanation":"Stroke-risk scoring estimates thromboembolic risk and supports decisions about oral anticoagulation.","reference_text":"2024 ESC Atrial Fibrillation Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/atrial-fibrillation/","dr_corazon_hint":"The score is for embolic prevention, not for diagnosing AF or choosing a rate-control drug.","display_order":17,"options":[{"key":"A","text":"Guide assessment for oral anticoagulation","correct":true},{"key":"B","text":"Diagnose AF from symptoms","correct":false},{"key":"C","text":"Measure ventricular rate","correct":false},{"key":"D","text":"Determine the QRS axis","correct":false}]},
  {"module_id":"basic-atrial-fibrillation","external_id":"basic-af-018","stem":"How should a high bleeding-risk score generally be used?","clinical_scenario":null,"topic":"Diagnosis","subtopic":"Bleeding risk","difficulty":"intermediate","explanation":"Bleeding assessment should identify and correct modifiable risk factors and prompt closer follow-up, not automatically withhold indicated anticoagulation.","reference_text":"2024 ESC Atrial Fibrillation Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/atrial-fibrillation/","dr_corazon_hint":"It is a safety checklist, not a simple veto against stroke prevention.","display_order":18,"options":[{"key":"A","text":"Correct modifiable risks and plan closer review","correct":true},{"key":"B","text":"Automatically deny anticoagulation to every high-risk patient","correct":false},{"key":"C","text":"Ignore blood pressure and interacting drugs","correct":false},{"key":"D","text":"Use it to confirm the ECG diagnosis","correct":false}]},
  {"module_id":"basic-atrial-fibrillation","external_id":"basic-af-019","stem":"Which is included in the 2024 ESC AF-CARE framework?","clinical_scenario":null,"topic":"Treatment","subtopic":"AF-CARE","difficulty":"intermediate","explanation":"AF-CARE includes comorbidity and risk-factor management, avoidance of stroke and thromboembolism, reduction of symptoms and dynamic evaluation.","reference_text":"2024 ESC Atrial Fibrillation Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/atrial-fibrillation/","dr_corazon_hint":"CARE is broader than rate control: comorbidities, anticoagulation, symptoms and reassessment all matter.","display_order":19,"options":[{"key":"A","text":"Comorbidity management, stroke prevention, symptom control and reassessment","correct":true},{"key":"B","text":"Cardioversion for every patient without assessment","correct":false},{"key":"C","text":"Aspirin alone for all stroke prevention","correct":false},{"key":"D","text":"Rate control with no follow-up","correct":false}]},
  {"module_id":"basic-atrial-fibrillation","external_id":"basic-af-020","stem":"Which oral anticoagulants are generally preferred for eligible patients with non-valvular AF?","clinical_scenario":null,"topic":"Treatment","subtopic":"Anticoagulation","difficulty":"foundation","explanation":"DOACs are generally preferred over vitamin K antagonists in eligible patients, except in mechanical valves or moderate-to-severe rheumatic mitral stenosis.","reference_text":"2024 ESC Atrial Fibrillation Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/atrial-fibrillation/","dr_corazon_hint":"Choose the modern oral anticoagulants, while remembering the important mechanical-valve and rheumatic-mitral-stenosis exceptions.","display_order":20,"options":[{"key":"A","text":"Direct oral anticoagulants","correct":true},{"key":"B","text":"Aspirin alone","correct":false},{"key":"C","text":"Clopidogrel alone","correct":false},{"key":"D","text":"No stroke prevention is needed if asymptomatic","correct":false}]},
  {"module_id":"basic-atrial-fibrillation","external_id":"basic-af-021","stem":"Which patient should generally receive a vitamin K antagonist rather than a DOAC for AF-related stroke prevention?","clinical_scenario":null,"topic":"Treatment","subtopic":"Anticoagulation exceptions","difficulty":"intermediate","explanation":"Mechanical prosthetic heart valves require vitamin K antagonist anticoagulation; DOACs are not recommended.","reference_text":"2024 ESC Atrial Fibrillation Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/atrial-fibrillation/","dr_corazon_hint":"The artificial valve type is the decisive clue.","display_order":21,"options":[{"key":"A","text":"A patient with a mechanical prosthetic valve","correct":true},{"key":"B","text":"A patient with uncomplicated hypertension","correct":false},{"key":"C","text":"A patient with well-controlled diabetes","correct":false},{"key":"D","text":"A patient with paroxysmal AF and no valve disease","correct":false}]},
  {"module_id":"basic-atrial-fibrillation","external_id":"basic-af-022","stem":"Which statement about aspirin for stroke prevention in atrial fibrillation is most accurate?","clinical_scenario":null,"topic":"Treatment","subtopic":"Antithrombotic therapy","difficulty":"foundation","explanation":"Antiplatelet therapy is not an adequate substitute for oral anticoagulation when anticoagulation is indicated for AF.","reference_text":"2024 ESC Atrial Fibrillation Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/atrial-fibrillation/","dr_corazon_hint":"Do not confuse platelet-rich arterial thrombosis with fibrin-rich left-atrial thromboembolism.","display_order":22,"options":[{"key":"A","text":"It is not an adequate substitute for indicated anticoagulation","correct":true},{"key":"B","text":"It is always equal to a DOAC","correct":false},{"key":"C","text":"It eliminates all bleeding risk","correct":false},{"key":"D","text":"It is mandatory with every anticoagulant indefinitely","correct":false}]},
  {"module_id":"basic-atrial-fibrillation","external_id":"basic-af-023","stem":"Which factor is essential when selecting the dose of a DOAC?","clinical_scenario":null,"topic":"Treatment","subtopic":"DOAC dosing","difficulty":"intermediate","explanation":"Renal function, age, weight and interacting drugs influence DOAC selection or dosing depending on the specific agent.","reference_text":"2024 ESC Atrial Fibrillation Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/atrial-fibrillation/","dr_corazon_hint":"A 'safer-looking' low dose may be ineffective if criteria are not met; use the label-based variables.","display_order":23,"options":[{"key":"A","text":"Renal function and the drug-specific dose-reduction criteria","correct":true},{"key":"B","text":"Eye colour","correct":false},{"key":"C","text":"Hand dominance","correct":false},{"key":"D","text":"The patient’s preferred tablet colour","correct":false}]},
  {"module_id":"basic-atrial-fibrillation","external_id":"basic-af-024","stem":"What is the immediate treatment when atrial fibrillation causes haemodynamic instability?","clinical_scenario":null,"topic":"Treatment","subtopic":"Cardioversion","difficulty":"foundation","explanation":"Urgent synchronized electrical cardioversion is indicated when AF causes instability.","reference_text":"2024 ESC Atrial Fibrillation Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/atrial-fibrillation/","dr_corazon_hint":"Unstable tachyarrhythmia means electricity first; synchronize to avoid shocking on the T wave.","display_order":24,"options":[{"key":"A","text":"Urgent synchronized electrical cardioversion","correct":true},{"key":"B","text":"Routine outpatient review in six months","correct":false},{"key":"C","text":"Aspirin only","correct":false},{"key":"D","text":"Unsynchronized shock in a conscious stable patient","correct":false}]},
  {"module_id":"basic-atrial-fibrillation","external_id":"basic-af-025","stem":"Which medicine is commonly used for ventricular rate control in atrial fibrillation?","clinical_scenario":null,"topic":"Treatment","subtopic":"Rate control","difficulty":"foundation","explanation":"Beta-blockers are commonly used for rate control, selected according to comorbidities and haemodynamic status.","reference_text":"2024 ESC Atrial Fibrillation Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/atrial-fibrillation/","dr_corazon_hint":"Choose an AV-node-slowing drug, not an antiplatelet or lipid-lowering drug.","display_order":25,"options":[{"key":"A","text":"Beta-blocker","correct":true},{"key":"B","text":"Aspirin","correct":false},{"key":"C","text":"Statin","correct":false},{"key":"D","text":"Proton-pump inhibitor","correct":false}]},
  {"module_id":"basic-atrial-fibrillation","external_id":"basic-af-026","stem":"Which rate-control medicine should generally be avoided in HFrEF?","clinical_scenario":null,"topic":"Treatment","subtopic":"Rate-control safety","difficulty":"intermediate","explanation":"Verapamil and diltiazem have negative inotropic effects and should generally be avoided in HFrEF.","reference_text":"2024 ESC Atrial Fibrillation Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/atrial-fibrillation/","dr_corazon_hint":"The trap is the non-dihydropyridine calcium-channel blocker in a weak ventricle.","display_order":26,"options":[{"key":"A","text":"Verapamil","correct":true},{"key":"B","text":"An evidence-based beta-blocker in a stable patient","correct":false},{"key":"C","text":"Digoxin in selected patients","correct":false},{"key":"D","text":"Anticoagulation when indicated","correct":false}]},
  {"module_id":"basic-atrial-fibrillation","external_id":"basic-af-027","stem":"Which patient may particularly benefit from rhythm control for symptom improvement?","clinical_scenario":null,"topic":"Treatment","subtopic":"Rhythm control","difficulty":"intermediate","explanation":"A symptomatic patient who remains limited despite adequate rate control may benefit from rhythm-control therapy after individualized assessment.","reference_text":"2024 ESC Atrial Fibrillation Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/atrial-fibrillation/","dr_corazon_hint":"Rhythm control is especially about symptoms and selected prognostic settings, not simply the presence of AF on an ECG.","display_order":27,"options":[{"key":"A","text":"A symptomatic patient despite adequate rate control","correct":true},{"key":"B","text":"Every asymptomatic patient without discussion","correct":false},{"key":"C","text":"A patient refusing any assessment","correct":false},{"key":"D","text":"A patient with no documented AF","correct":false}]},
  {"module_id":"basic-atrial-fibrillation","external_id":"basic-af-028","stem":"What is the main aim of catheter ablation in most patients with atrial fibrillation?","clinical_scenario":null,"topic":"Treatment","subtopic":"Ablation","difficulty":"foundation","explanation":"Catheter ablation is used primarily to reduce AF burden and improve symptoms and quality of life in suitable patients.","reference_text":"2024 ESC Atrial Fibrillation Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/atrial-fibrillation/","dr_corazon_hint":"Ablation treats the rhythm and symptoms; it does not automatically erase stroke risk.","display_order":28,"options":[{"key":"A","text":"Reduce AF burden and improve symptoms","correct":true},{"key":"B","text":"Guarantee that anticoagulation is never needed again","correct":false},{"key":"C","text":"Treat bacterial endocarditis","correct":false},{"key":"D","text":"Replace a mechanical valve","correct":false}]},
  {"module_id":"basic-atrial-fibrillation","external_id":"basic-af-029","stem":"Which statement about anticoagulation after apparently successful rhythm control is most accurate?","clinical_scenario":null,"topic":"Treatment","subtopic":"Post-rhythm stroke prevention","difficulty":"advanced","explanation":"Long-term anticoagulation decisions are based mainly on thromboembolic risk, not solely on apparent maintenance of sinus rhythm.","reference_text":"2024 ESC Atrial Fibrillation Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/atrial-fibrillation/","dr_corazon_hint":"Silent recurrence is possible; do not let a normal pulse replace formal stroke-risk assessment.","display_order":29,"options":[{"key":"A","text":"Base continuation on stroke risk rather than rhythm appearance alone","correct":true},{"key":"B","text":"Stop anticoagulation immediately after one normal ECG in every patient","correct":false},{"key":"C","text":"Use symptoms alone to exclude recurrence","correct":false},{"key":"D","text":"Replace anticoagulation with aspirin automatically","correct":false}]},
  {"module_id":"basic-atrial-fibrillation","external_id":"basic-af-030","stem":"Why is anticoagulation planning important before elective cardioversion of AF lasting more than 24–48 hours or of uncertain duration?","clinical_scenario":null,"topic":"Treatment","subtopic":"Cardioversion safety","difficulty":"intermediate","explanation":"Restoring atrial contraction can dislodge pre-existing atrial thrombus, so anticoagulation or an imaging-guided strategy is required according to guideline and local protocol.","reference_text":"2024 ESC Atrial Fibrillation Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/atrial-fibrillation/","dr_corazon_hint":"The concern is an unseen left-atrial appendage thrombus before the shock.","display_order":30,"options":[{"key":"A","text":"To reduce thromboembolism from pre-existing atrial thrombus","correct":true},{"key":"B","text":"To slow every ventricular rate permanently","correct":false},{"key":"C","text":"To prevent all skin burns","correct":false},{"key":"D","text":"Because cardioversion always causes valve stenosis","correct":false}]},
  {"module_id":"basic-atrial-fibrillation","external_id":"basic-af-031","stem":"Which finding suggests excessive rate-control therapy?","clinical_scenario":"A patient taking a beta-blocker and digoxin has dizziness, a ventricular rate of 38/min and AF.","topic":"Treatment","subtopic":"Bradycardia","difficulty":"intermediate","explanation":"Symptomatic marked bradycardia may reflect excessive AV-nodal blockade and requires urgent medication and conduction assessment.","reference_text":"2024 ESC Atrial Fibrillation Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/atrial-fibrillation/","dr_corazon_hint":"Rate control has gone too far: connect the dizziness to the ventricular rate of 38.","display_order":31,"options":[{"key":"A","text":"Symptomatic bradycardia","correct":true},{"key":"B","text":"A resting rate of 85/min without symptoms","correct":false},{"key":"C","text":"Normal blood pressure","correct":false},{"key":"D","text":"A normal potassium level","correct":false}]},
  {"module_id":"basic-atrial-fibrillation","external_id":"basic-af-032","stem":"Which comorbidity should be actively treated to improve AF outcomes?","clinical_scenario":null,"topic":"Treatment","subtopic":"Risk-factor care","difficulty":"foundation","explanation":"Obesity, hypertension, sleep apnoea, diabetes and excess alcohol are modifiable contributors to AF burden and recurrence.","reference_text":"2024 ESC Atrial Fibrillation Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/atrial-fibrillation/","dr_corazon_hint":"Choose a modifiable condition that changes the atrial substrate, not an unrelated minor complaint.","display_order":32,"options":[{"key":"A","text":"Obesity","correct":true},{"key":"B","text":"Myopia","correct":false},{"key":"C","text":"Healed wrist fracture","correct":false},{"key":"D","text":"Freckles","correct":false}]},
  {"module_id":"basic-atrial-fibrillation","external_id":"basic-af-033","stem":"Which counselling point is most important for a patient starting anticoagulation?","clinical_scenario":null,"topic":"Counselling","subtopic":"Adherence","difficulty":"foundation","explanation":"The patient should not stop anticoagulation without advice because protection falls rapidly and stroke risk returns.","reference_text":"2024 ESC Atrial Fibrillation Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/atrial-fibrillation/","dr_corazon_hint":"Emphasize continuity and a plan for missed doses rather than unsupervised stopping.","display_order":33,"options":[{"key":"A","text":"Do not stop it without clinical advice","correct":true},{"key":"B","text":"Take double doses routinely after any missed tablet","correct":false},{"key":"C","text":"Share tablets with another patient","correct":false},{"key":"D","text":"Stop whenever the pulse feels regular","correct":false}]},
  {"module_id":"basic-atrial-fibrillation","external_id":"basic-af-034","stem":"Which symptom should an anticoagulated patient report urgently?","clinical_scenario":null,"topic":"Counselling","subtopic":"Bleeding safety","difficulty":"foundation","explanation":"Black tarry stools may indicate gastrointestinal bleeding and require urgent assessment.","reference_text":"NICE Shared Decision Making and anticoagulation safety principles","reference_url":"https://www.nice.org.uk/guidance/ng197","dr_corazon_hint":"Look for a classic sign of internal bleeding, not a harmless normal variation.","display_order":34,"options":[{"key":"A","text":"Black tarry stools","correct":true},{"key":"B","text":"A single sneeze","correct":false},{"key":"C","text":"Mild hunger before lunch","correct":false},{"key":"D","text":"Normal urine colour","correct":false}]},
  {"module_id":"basic-atrial-fibrillation","external_id":"basic-af-035","stem":"A patient on anticoagulation falls and strikes the head. What advice is safest?","clinical_scenario":null,"topic":"Counselling","subtopic":"Head injury","difficulty":"foundation","explanation":"Head injury during anticoagulation can cause occult intracranial bleeding and needs urgent medical assessment according to local pathways.","reference_text":"Anticoagulation safety and NICE head-injury principles","reference_url":"https://www.nice.org.uk/guidance/ng232","dr_corazon_hint":"Anticoagulation lowers the threshold for urgent assessment after head trauma.","display_order":35,"options":[{"key":"A","text":"Seek urgent medical assessment","correct":true},{"key":"B","text":"Ignore it if there is no external bleeding","correct":false},{"key":"C","text":"Take an extra anticoagulant dose","correct":false},{"key":"D","text":"Wait one week before telling anyone","correct":false}]},
  {"module_id":"basic-atrial-fibrillation","external_id":"basic-af-036","stem":"Which symptom requires immediate stroke assessment in a patient with AF?","clinical_scenario":null,"topic":"Counselling","subtopic":"Stroke recognition","difficulty":"foundation","explanation":"Sudden unilateral weakness or speech disturbance may represent acute stroke and requires emergency assessment.","reference_text":"2024 ESC Atrial Fibrillation Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/atrial-fibrillation/","dr_corazon_hint":"Use FAST: face, arm, speech, time.","display_order":36,"options":[{"key":"A","text":"Sudden facial droop and arm weakness","correct":true},{"key":"B","text":"Long-standing mild dandruff","correct":false},{"key":"C","text":"Transient hunger","correct":false},{"key":"D","text":"A painless callus","correct":false}]},
  {"module_id":"basic-atrial-fibrillation","external_id":"basic-af-037","stem":"A patient says, 'I do not feel palpitations, so I cannot have AF.' What is the best response?","clinical_scenario":null,"topic":"Counselling","subtopic":"Asymptomatic AF","difficulty":"foundation","explanation":"AF may be asymptomatic; objective rhythm documentation and risk assessment remain important.","reference_text":"2024 ESC Atrial Fibrillation Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/atrial-fibrillation/","dr_corazon_hint":"Symptoms are an unreliable monitor of rhythm and stroke risk.","display_order":37,"options":[{"key":"A","text":"AF can occur without symptoms, so ECG evidence matters","correct":true},{"key":"B","text":"You are correct; asymptomatic AF does not exist","correct":false},{"key":"C","text":"Only chest pain can indicate AF","correct":false},{"key":"D","text":"Stroke prevention is unnecessary without palpitations","correct":false}]},
  {"module_id":"basic-atrial-fibrillation","external_id":"basic-af-038","stem":"Which statement best compares rate control and rhythm control?","clinical_scenario":null,"topic":"Treatment","subtopic":"Strategy","difficulty":"intermediate","explanation":"Rate control manages ventricular rate while accepting AF; rhythm control attempts to restore or maintain sinus rhythm. Stroke prevention is assessed independently.","reference_text":"2024 ESC Atrial Fibrillation Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/atrial-fibrillation/","dr_corazon_hint":"One strategy controls speed, the other targets the rhythm; neither alone answers the anticoagulation question.","display_order":38,"options":[{"key":"A","text":"Rate control slows the ventricle; rhythm control targets sinus rhythm","correct":true},{"key":"B","text":"They are identical strategies","correct":false},{"key":"C","text":"Rate control always eliminates AF","correct":false},{"key":"D","text":"Rhythm control removes all stroke risk","correct":false}]},
  {"module_id":"basic-atrial-fibrillation","external_id":"basic-af-039","stem":"Which factor can raise the risk of digoxin toxicity?","clinical_scenario":null,"topic":"Treatment","subtopic":"Digoxin safety","difficulty":"advanced","explanation":"Renal impairment can reduce digoxin clearance; hypokalaemia and drug interactions also increase toxicity risk.","reference_text":"2024 ESC Atrial Fibrillation Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/atrial-fibrillation/","dr_corazon_hint":"Digoxin depends heavily on renal clearance and has a narrow therapeutic margin.","display_order":39,"options":[{"key":"A","text":"Renal impairment","correct":true},{"key":"B","text":"Normal renal function","correct":false},{"key":"C","text":"A normal potassium level","correct":false},{"key":"D","text":"Adequate hydration alone","correct":false}]},
  {"module_id":"basic-atrial-fibrillation","external_id":"basic-af-040","stem":"A patient with AF has chest pain and a ventricular rate of 180/min but normal blood pressure. What is the priority?","clinical_scenario":null,"topic":"Treatment","subtopic":"Acute assessment","difficulty":"advanced","explanation":"Ongoing ischaemic chest pain may indicate instability; urgent assessment and synchronized cardioversion should be considered if AF is causing ischaemia.","reference_text":"2024 ESC Atrial Fibrillation Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/atrial-fibrillation/","dr_corazon_hint":"Normal blood pressure does not guarantee stability; ongoing myocardial ischaemia is itself a red flag.","display_order":40,"options":[{"key":"A","text":"Treat as potentially unstable and urgently assess for cardioversion","correct":true},{"key":"B","text":"Discharge without ECG monitoring","correct":false},{"key":"C","text":"Wait several weeks before reassessment","correct":false},{"key":"D","text":"Give aspirin alone and ignore the rhythm","correct":false}]},
  {"module_id":"basic-atrial-fibrillation","external_id":"basic-af-041","stem":"Why should stroke risk be reassessed over time?","clinical_scenario":null,"topic":"Diagnosis","subtopic":"Dynamic risk","difficulty":"intermediate","explanation":"Age and comorbidities change, so a previously low-risk patient may later benefit from anticoagulation.","reference_text":"2024 ESC Atrial Fibrillation Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/atrial-fibrillation/","dr_corazon_hint":"Risk scores are snapshots, not lifetime labels.","display_order":41,"options":[{"key":"A","text":"Age and comorbidities change over time","correct":true},{"key":"B","text":"The ECG machine changes the score","correct":false},{"key":"C","text":"Stroke risk disappears after the first visit","correct":false},{"key":"D","text":"Only symptoms determine risk","correct":false}]},
  {"module_id":"basic-atrial-fibrillation","external_id":"basic-af-042","stem":"Which finding is most consistent with atrial flutter rather than atrial fibrillation?","clinical_scenario":null,"topic":"Diagnosis","subtopic":"Differential rhythm","difficulty":"advanced","explanation":"Typical atrial flutter often produces organized saw-tooth atrial activity, commonly with a regular ventricular response at fixed block.","reference_text":"2024 ESC Atrial Fibrillation Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/atrial-fibrillation/","dr_corazon_hint":"Flutter is organized and repetitive; AF is chaotic without discrete repeating P waves.","display_order":42,"options":[{"key":"A","text":"Regular saw-tooth atrial waves","correct":true},{"key":"B","text":"Completely irregular RR intervals with absent organized atrial activity","correct":false},{"key":"C","text":"Progressive PR prolongation","correct":false},{"key":"D","text":"ST elevation in contiguous leads","correct":false}]},
  {"module_id":"basic-atrial-fibrillation","external_id":"basic-af-043","stem":"Why may pulse rate be lower than the apical heart rate in AF?","clinical_scenario":null,"topic":"Symptoms and signs","subtopic":"Pulse deficit","difficulty":"advanced","explanation":"Some ventricular contractions occur too early or weakly to generate a palpable peripheral pulse, producing a pulse deficit.","reference_text":"Undergraduate cardiovascular examination principles","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/atrial-fibrillation/","dr_corazon_hint":"Not every ventricular contraction produces enough stroke volume to reach the wrist.","display_order":43,"options":[{"key":"A","text":"Some ventricular beats do not produce a palpable peripheral pulse","correct":true},{"key":"B","text":"The atria never depolarize","correct":false},{"key":"C","text":"Every QRS is followed by two pulses","correct":false},{"key":"D","text":"The radial artery is always occluded","correct":false}]},
  {"module_id":"basic-atrial-fibrillation","external_id":"basic-af-044","stem":"Which statement about AF caused during an acute illness is safest?","clinical_scenario":null,"topic":"Causes","subtopic":"Trigger-associated AF","difficulty":"advanced","explanation":"AF during acute illness may recur and still requires follow-up and stroke-risk reassessment rather than being dismissed as harmless.","reference_text":"2024 ESC Atrial Fibrillation Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/atrial-fibrillation/","dr_corazon_hint":"A reversible trigger does not guarantee a permanently reversible atrial substrate.","display_order":44,"options":[{"key":"A","text":"Arrange follow-up because recurrence and stroke risk may persist","correct":true},{"key":"B","text":"It can always be ignored after discharge","correct":false},{"key":"C","text":"It never requires ECG documentation","correct":false},{"key":"D","text":"It proves the patient has no structural disease","correct":false}]},
  {"module_id":"basic-atrial-fibrillation","external_id":"basic-af-045","stem":"Which communication technique checks whether a patient understands the anticoagulation plan?","clinical_scenario":null,"topic":"Counselling","subtopic":"Teach-back","difficulty":"foundation","explanation":"Teach-back asks the patient to explain the plan in their own words and reveals misunderstandings.","reference_text":"NICE Shared Decision Making NG197","reference_url":"https://www.nice.org.uk/guidance/ng197","dr_corazon_hint":"Do not ask only 'Do you understand?'; ask the patient to demonstrate understanding.","display_order":45,"options":[{"key":"A","text":"Ask the patient to explain the plan back in their own words","correct":true},{"key":"B","text":"Give more jargon","correct":false},{"key":"C","text":"Avoid questions","correct":false},{"key":"D","text":"Speak only to relatives without permission","correct":false}]},
  {"module_id":"basic-atrial-fibrillation","external_id":"basic-af-046","stem":"A patient asks whether a regular pulse today means anticoagulation can be stopped. What is the best answer?","clinical_scenario":null,"topic":"Counselling","subtopic":"Stroke prevention","difficulty":"intermediate","explanation":"A regular pulse does not exclude intermittent AF, and anticoagulation decisions depend mainly on stroke risk and specialist review.","reference_text":"2024 ESC Atrial Fibrillation Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/atrial-fibrillation/","dr_corazon_hint":"One moment of sinus rhythm is not proof of permanent freedom from AF.","display_order":46,"options":[{"key":"A","text":"Do not stop it; discuss stroke risk and rhythm history with the clinician","correct":true},{"key":"B","text":"Stop immediately after any regular pulse","correct":false},{"key":"C","text":"Replace it with an NSAID","correct":false},{"key":"D","text":"Double the dose on days with palpitations","correct":false}]},
  {"module_id":"basic-atrial-fibrillation","external_id":"basic-af-047","stem":"Which advice about alcohol is appropriate for a patient with recurrent AF?","clinical_scenario":null,"topic":"Counselling","subtopic":"Lifestyle","difficulty":"foundation","explanation":"Reducing or avoiding excess alcohol can reduce AF triggers and recurrence and should be individualized.","reference_text":"2024 ESC Atrial Fibrillation Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/atrial-fibrillation/","dr_corazon_hint":"This is a modifiable trigger with a dose-related relationship to AF.","display_order":47,"options":[{"key":"A","text":"Reduce or avoid excess alcohol","correct":true},{"key":"B","text":"Binge drinking protects against AF","correct":false},{"key":"C","text":"Alcohol has no relationship to AF","correct":false},{"key":"D","text":"Replace anticoagulation with alcohol reduction","correct":false}]},
  {"module_id":"basic-atrial-fibrillation","external_id":"basic-af-048","stem":"Which statement best explains why blood pressure control matters in AF?","clinical_scenario":null,"topic":"Treatment","subtopic":"Risk-factor management","difficulty":"intermediate","explanation":"Hypertension contributes to atrial remodeling, AF recurrence, stroke and bleeding risk; control improves comprehensive care.","reference_text":"2024 ESC Atrial Fibrillation Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/atrial-fibrillation/","dr_corazon_hint":"One risk factor affects both the rhythm substrate and thromboembolic or bleeding outcomes.","display_order":48,"options":[{"key":"A","text":"It reduces an important driver of AF and vascular risk","correct":true},{"key":"B","text":"It guarantees AF will never recur","correct":false},{"key":"C","text":"It makes ECG monitoring unnecessary","correct":false},{"key":"D","text":"It replaces anticoagulation in high-risk patients","correct":false}]},
  {"module_id":"basic-atrial-fibrillation","external_id":"basic-af-049","stem":"Which follow-up plan is most complete for atrial fibrillation?","clinical_scenario":null,"topic":"Treatment","subtopic":"Reassessment","difficulty":"intermediate","explanation":"AF care requires dynamic reassessment of comorbidities, symptoms, rate or rhythm, stroke risk, bleeding risks, renal function and adherence.","reference_text":"2024 ESC Atrial Fibrillation Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/atrial-fibrillation/","dr_corazon_hint":"Use the final letter in AF-CARE: evaluation and reassessment are continuous.","display_order":49,"options":[{"key":"A","text":"Reassess symptoms, rhythm, stroke risk, bleeding risks, renal function and adherence","correct":true},{"key":"B","text":"No follow-up once one prescription is written","correct":false},{"key":"C","text":"Review only if the patient feels palpitations","correct":false},{"key":"D","text":"Measure only cholesterol forever","correct":false}]},
  {"module_id":"basic-atrial-fibrillation","external_id":"basic-af-050","stem":"A patient with AF asks what the two main treatment goals are. Which answer is best?","clinical_scenario":null,"topic":"Counselling","subtopic":"Treatment goals","difficulty":"foundation","explanation":"Management aims to prevent stroke and thromboembolism and to reduce symptoms through rate or rhythm control, alongside comorbidity care.","reference_text":"2024 ESC Atrial Fibrillation Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/atrial-fibrillation/","dr_corazon_hint":"Separate protection from stroke from control of how the patient feels.","display_order":50,"options":[{"key":"A","text":"Prevent stroke and improve symptoms","correct":true},{"key":"B","text":"Lower cholesterol and treat infection only","correct":false},{"key":"C","text":"Avoid all physical activity and stop monitoring","correct":false},{"key":"D","text":"Perform ablation in every patient","correct":false}]}
]
$questions$::jsonb) as x(
  module_id text, external_id text, stem text, clinical_scenario text,
  topic text, subtopic text, difficulty text, explanation text,
  reference_text text, reference_url text, dr_corazon_hint text,
  display_order integer, options jsonb
);

-- Acute Coronary Syndromes: 50 questions
insert into acl_basic_question_seed
select * from jsonb_to_recordset($questions$
[
  {"module_id":"basic-acute-coronary-syndromes","external_id":"basic-acs-001","stem":"Which conditions are included in acute coronary syndromes?","clinical_scenario":null,"topic":"Definition","subtopic":"Spectrum","difficulty":"foundation","explanation":"ACS includes STEMI, NSTEMI and unstable angina.","reference_text":"2023 ESC Acute Coronary Syndromes Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/acute-coronary-syndromes/","dr_corazon_hint":"Think of the complete acute ischaemic spectrum, not chronic stable angina.","display_order":1,"options":[{"key":"A","text":"STEMI, NSTEMI and unstable angina","correct":true},{"key":"B","text":"Stable angina only","correct":false},{"key":"C","text":"Pericarditis and myocarditis only","correct":false},{"key":"D","text":"Aortic stenosis only","correct":false}]},
  {"module_id":"basic-acute-coronary-syndromes","external_id":"basic-acs-002","stem":"What is required to diagnose acute myocardial infarction?","clinical_scenario":null,"topic":"Definition","subtopic":"Myocardial infarction","difficulty":"intermediate","explanation":"Acute MI requires acute myocardial injury, shown by a rise or fall in troponin with at least one value above the 99th percentile, plus clinical evidence of ischaemia.","reference_text":"Fourth Universal Definition of MI and 2023 ESC ACS Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/acute-coronary-syndromes/","dr_corazon_hint":"Troponin elevation alone means injury; add evidence of ischaemia to call it MI.","display_order":2,"options":[{"key":"A","text":"Acute troponin change plus evidence of myocardial ischaemia","correct":true},{"key":"B","text":"Any single troponin elevation regardless of context","correct":false},{"key":"C","text":"Chest pain with a permanently normal troponin in every case","correct":false},{"key":"D","text":"ST elevation without any clinical assessment","correct":false}]},
  {"module_id":"basic-acute-coronary-syndromes","external_id":"basic-acs-003","stem":"Which statement best distinguishes NSTEMI from unstable angina?","clinical_scenario":null,"topic":"Definition","subtopic":"NSTEMI versus unstable angina","difficulty":"foundation","explanation":"NSTEMI has biomarker evidence of myocardial necrosis; unstable angina has ischaemic symptoms without acute troponin-defined necrosis.","reference_text":"2023 ESC Acute Coronary Syndromes Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/acute-coronary-syndromes/","dr_corazon_hint":"The discriminator is myocardial necrosis detected by troponin, not the severity of pain alone.","display_order":3,"options":[{"key":"A","text":"NSTEMI has acute troponin evidence of myocardial necrosis","correct":true},{"key":"B","text":"Unstable angina always has ST elevation","correct":false},{"key":"C","text":"NSTEMI never causes chest pain","correct":false},{"key":"D","text":"They are separated only by age","correct":false}]},
  {"module_id":"basic-acute-coronary-syndromes","external_id":"basic-acs-004","stem":"What is the usual mechanism of a type 1 myocardial infarction?","clinical_scenario":null,"topic":"Causes","subtopic":"Atherothrombosis","difficulty":"foundation","explanation":"Type 1 MI usually results from atherosclerotic plaque rupture or erosion with superimposed coronary thrombosis.","reference_text":"2023 ESC Acute Coronary Syndromes Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/acute-coronary-syndromes/","dr_corazon_hint":"Choose acute coronary atherothrombosis rather than a supply-demand imbalance.","display_order":4,"options":[{"key":"A","text":"Plaque disruption with coronary thrombosis","correct":true},{"key":"B","text":"Isolated anaemia without coronary thrombosis","correct":false},{"key":"C","text":"Stable valve disease only","correct":false},{"key":"D","text":"Viral infection of the pericardium","correct":false}]},
  {"module_id":"basic-acute-coronary-syndromes","external_id":"basic-acs-005","stem":"Which scenario best illustrates a possible type 2 myocardial infarction?","clinical_scenario":null,"topic":"Causes","subtopic":"Supply-demand imbalance","difficulty":"intermediate","explanation":"Severe anaemia with tachycardia can create myocardial oxygen supply-demand imbalance without acute coronary thrombosis.","reference_text":"Fourth Universal Definition of MI and 2023 ESC ACS Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/acute-coronary-syndromes/","dr_corazon_hint":"Look for a major supply-demand stressor rather than plaque rupture.","display_order":5,"options":[{"key":"A","text":"Severe anaemia with sustained tachycardia and ischaemia","correct":true},{"key":"B","text":"Plaque rupture with an occlusive thrombus","correct":false},{"key":"C","text":"Stable asymptomatic coronary calcium","correct":false},{"key":"D","text":"Uncomplicated allergic rhinitis","correct":false}]},
  {"module_id":"basic-acute-coronary-syndromes","external_id":"basic-acs-006","stem":"Which is a major modifiable risk factor for ACS?","clinical_scenario":null,"topic":"Causes","subtopic":"Risk factors","difficulty":"foundation","explanation":"Cigarette smoking is a major modifiable cardiovascular risk factor that promotes atherosclerosis and thrombosis.","reference_text":"2023 ESC Acute Coronary Syndromes Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/acute-coronary-syndromes/","dr_corazon_hint":"Choose the exposure that injures endothelium and increases thrombogenicity.","display_order":6,"options":[{"key":"A","text":"Cigarette smoking","correct":true},{"key":"B","text":"Eye colour","correct":false},{"key":"C","text":"Hand dominance","correct":false},{"key":"D","text":"Remote tonsillectomy","correct":false}]},
  {"module_id":"basic-acute-coronary-syndromes","external_id":"basic-acs-007","stem":"Which non-atherosclerotic coronary condition can cause ACS, especially in younger women?","clinical_scenario":null,"topic":"Causes","subtopic":"SCAD","difficulty":"advanced","explanation":"Spontaneous coronary artery dissection is an important non-atherosclerotic cause of ACS, particularly in younger women and around pregnancy.","reference_text":"2023 ESC Acute Coronary Syndromes Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/acute-coronary-syndromes/","dr_corazon_hint":"The clue is a younger woman without the usual atherosclerotic profile.","display_order":7,"options":[{"key":"A","text":"Spontaneous coronary artery dissection","correct":true},{"key":"B","text":"Chronic venous insufficiency","correct":false},{"key":"C","text":"Uncomplicated sinusitis","correct":false},{"key":"D","text":"Mitral valve prolapse without ischaemia","correct":false}]},
  {"module_id":"basic-acute-coronary-syndromes","external_id":"basic-acs-008","stem":"Which substance may precipitate ACS through vasospasm and thrombosis?","clinical_scenario":null,"topic":"Causes","subtopic":"Stimulants","difficulty":"foundation","explanation":"Cocaine can increase myocardial oxygen demand, cause coronary vasospasm and promote thrombosis.","reference_text":"2023 ESC Acute Coronary Syndromes Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/acute-coronary-syndromes/","dr_corazon_hint":"Think of a stimulant associated with severe hypertension and coronary spasm.","display_order":8,"options":[{"key":"A","text":"Cocaine","correct":true},{"key":"B","text":"Oral rehydration solution","correct":false},{"key":"C","text":"Topical moisturizer","correct":false},{"key":"D","text":"Routine influenza vaccine","correct":false}]},
  {"module_id":"basic-acute-coronary-syndromes","external_id":"basic-acs-009","stem":"Which description is most typical of ischaemic chest discomfort?","clinical_scenario":null,"topic":"Symptoms and signs","subtopic":"Chest pain","difficulty":"foundation","explanation":"ACS discomfort is commonly central pressure, heaviness or tightness that may radiate and lasts more than a few minutes.","reference_text":"2023 ESC Acute Coronary Syndromes Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/acute-coronary-syndromes/","dr_corazon_hint":"Choose pressure or heaviness rather than a one-second localized sharp sensation.","display_order":9,"options":[{"key":"A","text":"Central pressure radiating to the arm or jaw","correct":true},{"key":"B","text":"One-second fingertip pain reproducible only by touching a rib","correct":false},{"key":"C","text":"Itchy skin without discomfort","correct":false},{"key":"D","text":"Pain limited to moving one toe","correct":false}]},
  {"module_id":"basic-acute-coronary-syndromes","external_id":"basic-acs-010","stem":"Which associated symptom commonly accompanies ACS?","clinical_scenario":null,"topic":"Symptoms and signs","subtopic":"Associated symptoms","difficulty":"foundation","explanation":"Sweating, nausea, dyspnoea and a sense of impending doom commonly accompany acute myocardial ischaemia.","reference_text":"2023 ESC Acute Coronary Syndromes Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/acute-coronary-syndromes/","dr_corazon_hint":"Autonomic activation often produces a cold sweat and nausea.","display_order":10,"options":[{"key":"A","text":"Profuse sweating","correct":true},{"key":"B","text":"Isolated ear itching","correct":false},{"key":"C","text":"Painless hiccups only","correct":false},{"key":"D","text":"Chronic hair loss","correct":false}]},
  {"module_id":"basic-acute-coronary-syndromes","external_id":"basic-acs-011","stem":"Which group is more likely to present with atypical ACS symptoms such as dyspnoea or weakness?","clinical_scenario":null,"topic":"Symptoms and signs","subtopic":"Atypical presentation","difficulty":"foundation","explanation":"Older adults, women and people with diabetes may present without classic chest pain.","reference_text":"2023 ESC Acute Coronary Syndromes Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/acute-coronary-syndromes/","dr_corazon_hint":"Neuropathy, age and sex-related presentation differences can hide the classic pain pattern.","display_order":11,"options":[{"key":"A","text":"Older adults and people with diabetes","correct":true},{"key":"B","text":"Only healthy teenagers","correct":false},{"key":"C","text":"Only patients with myopia","correct":false},{"key":"D","text":"No group has atypical presentations","correct":false}]},
  {"module_id":"basic-acute-coronary-syndromes","external_id":"basic-acs-012","stem":"Which examination finding suggests cardiogenic shock in ACS?","clinical_scenario":null,"topic":"Symptoms and signs","subtopic":"Shock","difficulty":"foundation","explanation":"Hypotension, cool clammy extremities, altered consciousness and oliguria suggest poor perfusion and cardiogenic shock.","reference_text":"2023 ESC Acute Coronary Syndromes Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/acute-coronary-syndromes/","dr_corazon_hint":"Look for the 'cold' signs of inadequate cardiac output.","display_order":12,"options":[{"key":"A","text":"Hypotension with cool clammy extremities","correct":true},{"key":"B","text":"Normal perfusion and normal blood pressure","correct":false},{"key":"C","text":"Isolated mild ankle itch","correct":false},{"key":"D","text":"A painless skin tag","correct":false}]},
  {"module_id":"basic-acute-coronary-syndromes","external_id":"basic-acs-013","stem":"A new loud systolic murmur develops after myocardial infarction with sudden pulmonary oedema. What should be suspected?","clinical_scenario":null,"topic":"Symptoms and signs","subtopic":"Mechanical complications","difficulty":"advanced","explanation":"Acute mitral regurgitation from papillary muscle dysfunction or rupture is a life-threatening mechanical complication.","reference_text":"2023 ESC Acute Coronary Syndromes Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/acute-coronary-syndromes/","dr_corazon_hint":"The combination of a new murmur and abrupt pulmonary oedema after MI is the key.","display_order":13,"options":[{"key":"A","text":"Acute severe mitral regurgitation","correct":true},{"key":"B","text":"Stable mild aortic sclerosis","correct":false},{"key":"C","text":"Uncomplicated pericarditis only","correct":false},{"key":"D","text":"Chronic venous insufficiency","correct":false}]},
  {"module_id":"basic-acute-coronary-syndromes","external_id":"basic-acs-014","stem":"How quickly should a 12-lead ECG be obtained in suspected ACS?","clinical_scenario":null,"topic":"Diagnosis","subtopic":"ECG timing","difficulty":"foundation","explanation":"A 12-lead ECG should be obtained and interpreted as early as possible, ideally within 10 minutes of first medical contact.","reference_text":"2023 ESC Acute Coronary Syndromes Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/acute-coronary-syndromes/","dr_corazon_hint":"ACS is time-sensitive; the correct answer is measured in minutes, not hours.","display_order":14,"options":[{"key":"A","text":"Ideally within 10 minutes","correct":true},{"key":"B","text":"After 24 hours","correct":false},{"key":"C","text":"Only after troponin returns","correct":false},{"key":"D","text":"At the routine follow-up visit","correct":false}]},
  {"module_id":"basic-acute-coronary-syndromes","external_id":"basic-acs-015","stem":"What should be done if the first ECG is nondiagnostic but ischaemic symptoms continue?","clinical_scenario":null,"topic":"Diagnosis","subtopic":"Serial ECG","difficulty":"foundation","explanation":"Repeat ECGs and additional leads may reveal dynamic or initially hidden ischaemic changes.","reference_text":"2023 ESC Acute Coronary Syndromes Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/acute-coronary-syndromes/","dr_corazon_hint":"The ECG is a snapshot; ongoing symptoms demand another snapshot.","display_order":15,"options":[{"key":"A","text":"Repeat the ECG and consider additional leads","correct":true},{"key":"B","text":"Exclude ACS permanently","correct":false},{"key":"C","text":"Discharge without reassessment","correct":false},{"key":"D","text":"Wait one month","correct":false}]},
  {"module_id":"basic-acute-coronary-syndromes","external_id":"basic-acs-016","stem":"Which leads are useful when posterior myocardial infarction is suspected?","clinical_scenario":null,"topic":"Diagnosis","subtopic":"Posterior leads","difficulty":"intermediate","explanation":"Posterior leads V7–V9 can detect posterior ST elevation when the standard ECG shows reciprocal anterior ST depression.","reference_text":"2023 ESC Acute Coronary Syndromes Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/acute-coronary-syndromes/","dr_corazon_hint":"Move the chest electrodes around the back to look directly at the posterior wall.","display_order":16,"options":[{"key":"A","text":"V7–V9","correct":true},{"key":"B","text":"aVR only","correct":false},{"key":"C","text":"V1 only","correct":false},{"key":"D","text":"No additional leads are useful","correct":false}]},
  {"module_id":"basic-acute-coronary-syndromes","external_id":"basic-acs-017","stem":"Which additional leads are useful in an inferior STEMI with hypotension?","clinical_scenario":null,"topic":"Diagnosis","subtopic":"Right ventricular infarction","difficulty":"intermediate","explanation":"Right-sided leads, especially V3R–V4R, help detect right ventricular infarction.","reference_text":"2023 ESC Acute Coronary Syndromes Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/acute-coronary-syndromes/","dr_corazon_hint":"Inferior infarction plus hypotension should make you look at the right ventricle.","display_order":17,"options":[{"key":"A","text":"Right-sided leads V3R–V4R","correct":true},{"key":"B","text":"Posterior leads only in every case","correct":false},{"key":"C","text":"EEG electrodes","correct":false},{"key":"D","text":"No ECG extension is needed","correct":false}]},
  {"module_id":"basic-acute-coronary-syndromes","external_id":"basic-acs-018","stem":"What does a high-sensitivity cardiac troponin above the 99th percentile indicate by itself?","clinical_scenario":null,"topic":"Diagnosis","subtopic":"Troponin","difficulty":"advanced","explanation":"It indicates myocardial injury, but clinical evidence of ischaemia and a rise or fall are needed to classify acute MI.","reference_text":"Fourth Universal Definition of MI and 2023 ESC ACS Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/acute-coronary-syndromes/","dr_corazon_hint":"Do not equate injury with infarction; myocarditis, HF, PE and renal disease can raise troponin.","display_order":18,"options":[{"key":"A","text":"Myocardial injury","correct":true},{"key":"B","text":"Definite type 1 MI in every patient","correct":false},{"key":"C","text":"Definite pulmonary embolism","correct":false},{"key":"D","text":"Normal myocardium","correct":false}]},
  {"module_id":"basic-acute-coronary-syndromes","external_id":"basic-acs-019","stem":"Why are serial troponin measurements used?","clinical_scenario":null,"topic":"Diagnosis","subtopic":"Serial biomarkers","difficulty":"foundation","explanation":"A rise or fall helps distinguish acute injury from chronically elevated troponin and supports rapid rule-in or rule-out algorithms.","reference_text":"2023 ESC Acute Coronary Syndromes Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/acute-coronary-syndromes/","dr_corazon_hint":"The trend provides time information that a single value cannot.","display_order":19,"options":[{"key":"A","text":"To detect a dynamic rise or fall","correct":true},{"key":"B","text":"To determine blood group","correct":false},{"key":"C","text":"To replace the ECG","correct":false},{"key":"D","text":"To diagnose valve stenosis","correct":false}]},
  {"module_id":"basic-acute-coronary-syndromes","external_id":"basic-acs-020","stem":"Which condition can elevate troponin without type 1 myocardial infarction?","clinical_scenario":null,"topic":"Diagnosis","subtopic":"Differential diagnosis","difficulty":"intermediate","explanation":"Myocarditis, heart failure, pulmonary embolism, renal disease and tachyarrhythmias can produce myocardial injury and elevated troponin.","reference_text":"2023 ESC Acute Coronary Syndromes Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/acute-coronary-syndromes/","dr_corazon_hint":"A positive biomarker has a differential diagnosis; choose another cardiac inflammatory cause of injury.","display_order":20,"options":[{"key":"A","text":"Myocarditis","correct":true},{"key":"B","text":"Simple myopia","correct":false},{"key":"C","text":"Cerumen impaction","correct":false},{"key":"D","text":"An old healed scar on the skin","correct":false}]},
  {"module_id":"basic-acute-coronary-syndromes","external_id":"basic-acs-021","stem":"Which medication should be given promptly in suspected ACS unless contraindicated?","clinical_scenario":null,"topic":"Treatment","subtopic":"Antiplatelet therapy","difficulty":"foundation","explanation":"Aspirin should be given promptly because it rapidly inhibits platelet aggregation and reduces recurrent ischaemic events.","reference_text":"2023 ESC Acute Coronary Syndromes Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/acute-coronary-syndromes/","dr_corazon_hint":"Choose the immediate first antiplatelet with a mortality benefit.","display_order":21,"options":[{"key":"A","text":"Aspirin","correct":true},{"key":"B","text":"NSAID","correct":false},{"key":"C","text":"Antibiotic in every case","correct":false},{"key":"D","text":"Oral iron","correct":false}]},
  {"module_id":"basic-acute-coronary-syndromes","external_id":"basic-acs-022","stem":"When is supplemental oxygen indicated in ACS?","clinical_scenario":null,"topic":"Treatment","subtopic":"Oxygen","difficulty":"foundation","explanation":"Oxygen is indicated for hypoxaemia, respiratory distress or another clear clinical need, not routinely when saturation is normal.","reference_text":"2023 ESC Acute Coronary Syndromes Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/acute-coronary-syndromes/","dr_corazon_hint":"Treat the low saturation, not the ACS label alone.","display_order":22,"options":[{"key":"A","text":"When the patient is hypoxaemic","correct":true},{"key":"B","text":"Routinely for every patient regardless of saturation","correct":false},{"key":"C","text":"Never, even in severe hypoxaemia","correct":false},{"key":"D","text":"Only after hospital discharge","correct":false}]},
  {"module_id":"basic-acute-coronary-syndromes","external_id":"basic-acs-023","stem":"In which situation should nitrates be avoided?","clinical_scenario":"A patient with inferior STEMI is hypotensive with suspected right ventricular infarction.","topic":"Treatment","subtopic":"Nitrates","difficulty":"intermediate","explanation":"Nitrates reduce preload and may cause profound hypotension in right ventricular infarction or existing hypotension.","reference_text":"2023 ESC Acute Coronary Syndromes Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/acute-coronary-syndromes/","dr_corazon_hint":"The right ventricle is preload-dependent; the blood pressure is already low.","display_order":23,"options":[{"key":"A","text":"Hypotension with suspected right ventricular infarction","correct":true},{"key":"B","text":"Stable hypertension with ongoing pain and no contraindication","correct":false},{"key":"C","text":"Normal oxygen saturation","correct":false},{"key":"D","text":"A normal chest X-ray","correct":false}]},
  {"module_id":"basic-acute-coronary-syndromes","external_id":"basic-acs-024","stem":"Which recent medication use is a contraindication to nitrates?","clinical_scenario":null,"topic":"Treatment","subtopic":"Drug interaction","difficulty":"intermediate","explanation":"Recent phosphodiesterase-5 inhibitor use can combine with nitrates to cause severe hypotension.","reference_text":"2023 ESC Acute Coronary Syndromes Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/acute-coronary-syndromes/","dr_corazon_hint":"Ask specifically about erectile-dysfunction medicines before giving nitrate.","display_order":24,"options":[{"key":"A","text":"A phosphodiesterase-5 inhibitor","correct":true},{"key":"B","text":"A statin","correct":false},{"key":"C","text":"A proton-pump inhibitor","correct":false},{"key":"D","text":"Paracetamol","correct":false}]},
  {"module_id":"basic-acute-coronary-syndromes","external_id":"basic-acs-025","stem":"What is the preferred reperfusion strategy for STEMI when it can be delivered within recommended time targets?","clinical_scenario":null,"topic":"Treatment","subtopic":"Reperfusion","difficulty":"foundation","explanation":"Timely primary PCI is the preferred reperfusion strategy for eligible STEMI patients.","reference_text":"2023 ESC Acute Coronary Syndromes Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/acute-coronary-syndromes/","dr_corazon_hint":"The best treatment mechanically opens the culprit artery quickly.","display_order":25,"options":[{"key":"A","text":"Primary PCI","correct":true},{"key":"B","text":"Elective stress testing before reperfusion","correct":false},{"key":"C","text":"Observation alone","correct":false},{"key":"D","text":"Routine antibiotics","correct":false}]},
  {"module_id":"basic-acute-coronary-syndromes","external_id":"basic-acs-026","stem":"When may fibrinolysis be considered for STEMI?","clinical_scenario":null,"topic":"Treatment","subtopic":"Fibrinolysis","difficulty":"intermediate","explanation":"Fibrinolysis may be considered early when timely primary PCI cannot be delivered and there are no contraindications, followed by urgent transfer to a PCI-capable centre.","reference_text":"2023 ESC Acute Coronary Syndromes Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/acute-coronary-syndromes/","dr_corazon_hint":"The trade-off is delay to PCI versus bleeding risk; this applies to eligible early STEMI, not NSTEMI.","display_order":26,"options":[{"key":"A","text":"Early STEMI when timely PCI is unavailable and no contraindication exists","correct":true},{"key":"B","text":"Every NSTEMI","correct":false},{"key":"C","text":"Any chest pain with a normal ECG","correct":false},{"key":"D","text":"Active intracranial bleeding","correct":false}]},
  {"module_id":"basic-acute-coronary-syndromes","external_id":"basic-acs-027","stem":"Which is an absolute contraindication to fibrinolysis?","clinical_scenario":null,"topic":"Treatment","subtopic":"Fibrinolysis safety","difficulty":"foundation","explanation":"Previous haemorrhagic stroke is a major absolute contraindication because fibrinolysis may cause catastrophic intracranial bleeding.","reference_text":"2023 ESC Acute Coronary Syndromes Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/acute-coronary-syndromes/","dr_corazon_hint":"Choose the history with the greatest intracranial bleeding danger.","display_order":27,"options":[{"key":"A","text":"Previous haemorrhagic stroke","correct":true},{"key":"B","text":"Controlled hypertension","correct":false},{"key":"C","text":"Remote uncomplicated appendicectomy","correct":false},{"key":"D","text":"Stable myopia","correct":false}]},
  {"module_id":"basic-acute-coronary-syndromes","external_id":"basic-acs-028","stem":"Which NSTE-ACS presentation requires an immediate invasive strategy?","clinical_scenario":null,"topic":"Treatment","subtopic":"Invasive timing","difficulty":"advanced","explanation":"Cardiogenic shock, ongoing refractory chest pain, life-threatening arrhythmia or recurrent dynamic ST changes are very-high-risk features requiring immediate invasive assessment.","reference_text":"2023 ESC Acute Coronary Syndromes Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/acute-coronary-syndromes/","dr_corazon_hint":"Identify active instability, not merely a positive troponin in a stable patient.","display_order":28,"options":[{"key":"A","text":"Cardiogenic shock with ongoing ischaemia","correct":true},{"key":"B","text":"Stable pain-free patient with normal serial tests","correct":false},{"key":"C","text":"Remote history of stable angina","correct":false},{"key":"D","text":"Mild controlled hypertension alone","correct":false}]},
  {"module_id":"basic-acute-coronary-syndromes","external_id":"basic-acs-029","stem":"What is the purpose of a P2Y12 inhibitor in ACS?","clinical_scenario":null,"topic":"Treatment","subtopic":"Dual antiplatelet therapy","difficulty":"foundation","explanation":"A P2Y12 inhibitor adds platelet inhibition to aspirin as part of dual antiplatelet therapy, selected according to the strategy and bleeding risk.","reference_text":"2023 ESC Acute Coronary Syndromes Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/acute-coronary-syndromes/","dr_corazon_hint":"This is the second antiplatelet component, not an anticoagulant or fibrinolytic.","display_order":29,"options":[{"key":"A","text":"Provide additional platelet inhibition with aspirin","correct":true},{"key":"B","text":"Dissolve every established thrombus instantly","correct":false},{"key":"C","text":"Replace reperfusion in STEMI","correct":false},{"key":"D","text":"Treat bacterial infection","correct":false}]},
  {"module_id":"basic-acute-coronary-syndromes","external_id":"basic-acs-030","stem":"Why is parenteral anticoagulation used in ACS?","clinical_scenario":null,"topic":"Treatment","subtopic":"Anticoagulation","difficulty":"intermediate","explanation":"Anticoagulation reduces thrombin generation and propagation of coronary thrombosis during the acute phase and invasive pathway.","reference_text":"2023 ESC Acute Coronary Syndromes Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/acute-coronary-syndromes/","dr_corazon_hint":"Antiplatelets target platelets; anticoagulants target the coagulation cascade.","display_order":30,"options":[{"key":"A","text":"Limit propagation of acute coronary thrombosis","correct":true},{"key":"B","text":"Treat pulmonary infection","correct":false},{"key":"C","text":"Lower LDL immediately as its only action","correct":false},{"key":"D","text":"Replace aspirin in every patient","correct":false}]},
  {"module_id":"basic-acute-coronary-syndromes","external_id":"basic-acs-031","stem":"Which medicine should usually be started early for secondary prevention after ACS?","clinical_scenario":null,"topic":"Treatment","subtopic":"Lipid lowering","difficulty":"foundation","explanation":"High-intensity statin therapy should be started early unless contraindicated, with further lipid lowering added when targets are not achieved.","reference_text":"2023 ESC Acute Coronary Syndromes Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/acute-coronary-syndromes/","dr_corazon_hint":"The benefit is plaque stabilization and long-term risk reduction, not immediate pain relief.","display_order":31,"options":[{"key":"A","text":"High-intensity statin","correct":true},{"key":"B","text":"Long-term NSAID","correct":false},{"key":"C","text":"Antibiotic for every patient","correct":false},{"key":"D","text":"Sedating antihistamine","correct":false}]},
  {"module_id":"basic-acute-coronary-syndromes","external_id":"basic-acs-032","stem":"Which complication is common in the first hours after acute MI and requires monitoring?","clinical_scenario":null,"topic":"Complications","subtopic":"Arrhythmia","difficulty":"foundation","explanation":"Ventricular arrhythmias may occur early after MI and can cause sudden cardiac arrest.","reference_text":"2023 ESC Acute Coronary Syndromes Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/acute-coronary-syndromes/","dr_corazon_hint":"Acute ischaemia creates an electrically unstable ventricle.","display_order":32,"options":[{"key":"A","text":"Ventricular tachyarrhythmia","correct":true},{"key":"B","text":"Cataract","correct":false},{"key":"C","text":"Chronic otitis externa","correct":false},{"key":"D","text":"Varicose veins","correct":false}]},
  {"module_id":"basic-acute-coronary-syndromes","external_id":"basic-acs-033","stem":"Which infarct location is especially associated with bradycardia or AV block?","clinical_scenario":null,"topic":"Complications","subtopic":"Conduction","difficulty":"intermediate","explanation":"Inferior MI, often involving the right coronary artery, may affect the AV node and cause bradycardia or AV block.","reference_text":"2023 ESC Acute Coronary Syndromes Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/acute-coronary-syndromes/","dr_corazon_hint":"Think of the artery that commonly supplies the AV node.","display_order":33,"options":[{"key":"A","text":"Inferior MI","correct":true},{"key":"B","text":"Isolated lateral wall ischaemia in every case","correct":false},{"key":"C","text":"No infarct can cause AV block","correct":false},{"key":"D","text":"Pericarditis only","correct":false}]},
  {"module_id":"basic-acute-coronary-syndromes","external_id":"basic-acs-034","stem":"A patient develops pleuritic chest pain relieved by sitting forward two days after MI. What is likely?","clinical_scenario":null,"topic":"Complications","subtopic":"Pericarditis","difficulty":"intermediate","explanation":"Early post-infarction pericarditis can cause pleuritic positional chest pain and a pericardial rub.","reference_text":"2023 ESC Acute Coronary Syndromes Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/acute-coronary-syndromes/","dr_corazon_hint":"The new pain is positional and pleuritic, unlike the original pressure-type ischaemic pain.","display_order":34,"options":[{"key":"A","text":"Post-infarction pericarditis","correct":true},{"key":"B","text":"Recurrent MI is proven by pain description alone","correct":false},{"key":"C","text":"Aortic stenosis","correct":false},{"key":"D","text":"Stable heart failure without inflammation","correct":false}]},
  {"module_id":"basic-acute-coronary-syndromes","external_id":"basic-acs-035","stem":"Sudden collapse with electromechanical dissociation several days after a large MI should raise concern for what?","clinical_scenario":null,"topic":"Complications","subtopic":"Free-wall rupture","difficulty":"advanced","explanation":"Left ventricular free-wall rupture can cause haemopericardium, tamponade and pulseless electrical activity.","reference_text":"2023 ESC Acute Coronary Syndromes Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/acute-coronary-syndromes/","dr_corazon_hint":"Think of a catastrophic mechanical rupture producing tamponade, not a primary electrical rhythm problem.","display_order":35,"options":[{"key":"A","text":"Left ventricular free-wall rupture","correct":true},{"key":"B","text":"Stable angina","correct":false},{"key":"C","text":"Chronic mild mitral regurgitation","correct":false},{"key":"D","text":"Uncomplicated sinus bradycardia","correct":false}]},
  {"module_id":"basic-acute-coronary-syndromes","external_id":"basic-acs-036","stem":"Which treatment reduces recurrent events by supporting exercise, education and risk-factor control after ACS?","clinical_scenario":null,"topic":"Treatment","subtopic":"Rehabilitation","difficulty":"foundation","explanation":"Cardiac rehabilitation is a core part of post-ACS care and improves functional recovery and risk-factor management.","reference_text":"2023 ESC Acute Coronary Syndromes Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/acute-coronary-syndromes/","dr_corazon_hint":"Recovery is a structured program, not just a discharge prescription.","display_order":36,"options":[{"key":"A","text":"Cardiac rehabilitation","correct":true},{"key":"B","text":"Permanent bed rest","correct":false},{"key":"C","text":"Unsupervised maximal exercise immediately","correct":false},{"key":"D","text":"Avoiding all follow-up","correct":false}]},
  {"module_id":"basic-acute-coronary-syndromes","external_id":"basic-acs-037","stem":"Which counselling point is essential after coronary stent implantation?","clinical_scenario":null,"topic":"Counselling","subtopic":"DAPT adherence","difficulty":"foundation","explanation":"Premature discontinuation of prescribed antiplatelet therapy can cause stent thrombosis; patients should seek specialist advice before stopping.","reference_text":"2023 ESC Acute Coronary Syndromes Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/acute-coronary-syndromes/","dr_corazon_hint":"The stent needs antiplatelet protection while healing; abrupt unsupervised stopping is dangerous.","display_order":37,"options":[{"key":"A","text":"Do not stop antiplatelet therapy without urgent specialist advice","correct":true},{"key":"B","text":"Stop both agents as soon as pain resolves","correct":false},{"key":"C","text":"Double doses whenever a tablet is missed","correct":false},{"key":"D","text":"Share the tablets with relatives","correct":false}]},
  {"module_id":"basic-acute-coronary-syndromes","external_id":"basic-acs-038","stem":"Which symptom after discharge requires emergency assessment?","clinical_scenario":null,"topic":"Counselling","subtopic":"Recurrent ischaemia","difficulty":"foundation","explanation":"Recurrent severe or persistent chest pressure may indicate reinfarction or stent thrombosis and requires emergency assessment.","reference_text":"2023 ESC Acute Coronary Syndromes Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/acute-coronary-syndromes/","dr_corazon_hint":"Safety-net for the symptom that could represent a re-occluded coronary artery.","display_order":38,"options":[{"key":"A","text":"Recurrent severe chest pressure lasting several minutes","correct":true},{"key":"B","text":"A mild itch at an adhesive site","correct":false},{"key":"C","text":"Transient hunger","correct":false},{"key":"D","text":"A painless callus","correct":false}]},
  {"module_id":"basic-acute-coronary-syndromes","external_id":"basic-acs-039","stem":"Why should smoking cessation be emphasized after ACS?","clinical_scenario":null,"topic":"Counselling","subtopic":"Smoking","difficulty":"foundation","explanation":"Stopping smoking substantially reduces recurrent cardiovascular risk and should be supported with behavioural and pharmacological help.","reference_text":"2023 ESC Acute Coronary Syndromes Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/acute-coronary-syndromes/","dr_corazon_hint":"This is one of the highest-yield modifiable secondary-prevention actions.","display_order":39,"options":[{"key":"A","text":"It markedly reduces recurrent cardiovascular risk","correct":true},{"key":"B","text":"It has no effect after the first MI","correct":false},{"key":"C","text":"It replaces all cardiac medicines","correct":false},{"key":"D","text":"Only passive smoking matters","correct":false}]},
  {"module_id":"basic-acute-coronary-syndromes","external_id":"basic-acs-040","stem":"Which explanation of a statin is best for a patient after ACS?","clinical_scenario":null,"topic":"Counselling","subtopic":"Statin purpose","difficulty":"foundation","explanation":"Statins lower atherogenic cholesterol, stabilize plaques and reduce recurrent cardiovascular events even when the patient feels well.","reference_text":"2023 ESC Acute Coronary Syndromes Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/acute-coronary-syndromes/","dr_corazon_hint":"Explain prevention and plaque stabilization, not symptom relief.","display_order":40,"options":[{"key":"A","text":"It lowers future risk by reducing LDL and stabilizing plaques","correct":true},{"key":"B","text":"It treats acute pain within seconds","correct":false},{"key":"C","text":"It dissolves the stent","correct":false},{"key":"D","text":"It is unnecessary if cholesterol was once normal","correct":false}]},
  {"module_id":"basic-acute-coronary-syndromes","external_id":"basic-acs-041","stem":"Which feature most strongly suggests aortic dissection rather than ACS?","clinical_scenario":null,"topic":"Diagnosis","subtopic":"Differential diagnosis","difficulty":"advanced","explanation":"Abrupt tearing pain radiating to the back with pulse or blood-pressure asymmetry raises concern for aortic dissection.","reference_text":"2023 ESC Acute Coronary Syndromes Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/acute-coronary-syndromes/","dr_corazon_hint":"This alternative diagnosis makes anticoagulation or fibrinolysis potentially disastrous.","display_order":41,"options":[{"key":"A","text":"Tearing pain to the back with unequal pulses","correct":true},{"key":"B","text":"Central pressure with sweating","correct":false},{"key":"C","text":"Dynamic troponin rise with ischaemic ECG changes","correct":false},{"key":"D","text":"Pain relieved after reperfusion","correct":false}]},
  {"module_id":"basic-acute-coronary-syndromes","external_id":"basic-acs-042","stem":"Which feature is more typical of acute pericarditis than ACS?","clinical_scenario":null,"topic":"Diagnosis","subtopic":"Differential diagnosis","difficulty":"intermediate","explanation":"Pericarditis classically causes sharp pleuritic pain improved by sitting forward, often with diffuse ST elevation and PR depression.","reference_text":"2023 ESC Acute Coronary Syndromes Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/acute-coronary-syndromes/","dr_corazon_hint":"Position and breathing change the pain; the ECG pattern is diffuse rather than territorial.","display_order":42,"options":[{"key":"A","text":"Pleuritic pain relieved by sitting forward","correct":true},{"key":"B","text":"Pressure pain with regional ST elevation","correct":false},{"key":"C","text":"Pain with a culprit coronary occlusion","correct":false},{"key":"D","text":"New regional wall-motion abnormality only","correct":false}]},
  {"module_id":"basic-acute-coronary-syndromes","external_id":"basic-acs-043","stem":"What is the role of bedside echocardiography in unstable suspected ACS?","clinical_scenario":null,"topic":"Diagnosis","subtopic":"Echocardiography","difficulty":"intermediate","explanation":"Bedside echo can assess ventricular function, regional wall motion and mechanical complications, but should not delay urgent reperfusion.","reference_text":"2023 ESC Acute Coronary Syndromes Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/acute-coronary-syndromes/","dr_corazon_hint":"It adds structural information, but 'time is muscle' remains the priority.","display_order":43,"options":[{"key":"A","text":"Identify dysfunction or complications without delaying reperfusion","correct":true},{"key":"B","text":"Replace the ECG and troponin in every patient","correct":false},{"key":"C","text":"Delay primary PCI until a full elective study is completed","correct":false},{"key":"D","text":"Measure platelet inhibition directly","correct":false}]},
  {"module_id":"basic-acute-coronary-syndromes","external_id":"basic-acs-044","stem":"A patient with suspected ACS has a normal first troponin one hour after pain began. What is the safest interpretation?","clinical_scenario":null,"topic":"Diagnosis","subtopic":"Early presentation","difficulty":"advanced","explanation":"A very early normal value may precede biomarker rise; repeat testing using a validated rapid algorithm and continued clinical assessment are needed.","reference_text":"2023 ESC Acute Coronary Syndromes Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/acute-coronary-syndromes/","dr_corazon_hint":"The clock started only one hour ago; biomarker kinetics are the trap.","display_order":44,"options":[{"key":"A","text":"Repeat troponin according to a validated algorithm","correct":true},{"key":"B","text":"Exclude MI permanently after one early value","correct":false},{"key":"C","text":"Ignore the ECG","correct":false},{"key":"D","text":"Diagnose unstable angina immediately without follow-up","correct":false}]},
  {"module_id":"basic-acute-coronary-syndromes","external_id":"basic-acs-045","stem":"Which communication method best supports informed consent before coronary angiography when time permits?","clinical_scenario":null,"topic":"Counselling","subtopic":"Consent","difficulty":"foundation","explanation":"Explain the indication, likely benefits, material risks and alternatives in understandable language and invite questions.","reference_text":"NICE Shared Decision Making NG197 and patient-centred ACS care","reference_url":"https://www.nice.org.uk/guidance/ng197","dr_corazon_hint":"Consent is a conversation tailored to what matters to the patient, not a signature alone.","display_order":45,"options":[{"key":"A","text":"Explain benefits, important risks and alternatives and invite questions","correct":true},{"key":"B","text":"Use unexplained technical jargon only","correct":false},{"key":"C","text":"Hide all risks","correct":false},{"key":"D","text":"Ask for a signature without discussion","correct":false}]},
  {"module_id":"basic-acute-coronary-syndromes","external_id":"basic-acs-046","stem":"Which communication technique is useful when explaining the discharge medication plan?","clinical_scenario":null,"topic":"Counselling","subtopic":"Teach-back","difficulty":"foundation","explanation":"Teach-back checks understanding by asking the patient to repeat the medication and emergency plan in their own words.","reference_text":"NICE Shared Decision Making NG197","reference_url":"https://www.nice.org.uk/guidance/ng197","dr_corazon_hint":"The patient should demonstrate understanding rather than simply answer yes.","display_order":46,"options":[{"key":"A","text":"Teach-back","correct":true},{"key":"B","text":"Avoiding all questions","correct":false},{"key":"C","text":"Giving an unreadable list only","correct":false},{"key":"D","text":"Speaking only to relatives without permission","correct":false}]},
  {"module_id":"basic-acute-coronary-syndromes","external_id":"basic-acs-047","stem":"Which statement about return to physical activity after ACS is most appropriate?","clinical_scenario":null,"topic":"Counselling","subtopic":"Recovery","difficulty":"foundation","explanation":"Activity should resume gradually through an individualized plan, ideally with cardiac rehabilitation and clinical guidance.","reference_text":"2023 ESC Acute Coronary Syndromes Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/acute-coronary-syndromes/","dr_corazon_hint":"Avoid both extremes: permanent bed rest and immediate maximal exertion.","display_order":47,"options":[{"key":"A","text":"Use a gradual individualized plan with cardiac rehabilitation","correct":true},{"key":"B","text":"Remain on bed rest forever","correct":false},{"key":"C","text":"Begin maximal exercise the day after discharge without review","correct":false},{"key":"D","text":"Physical activity has no role in recovery","correct":false}]},
  {"module_id":"basic-acute-coronary-syndromes","external_id":"basic-acs-048","stem":"Which secondary-prevention target should be addressed after ACS?","clinical_scenario":null,"topic":"Treatment","subtopic":"Risk-factor control","difficulty":"foundation","explanation":"Blood pressure, lipids, diabetes, smoking, weight, activity and adherence all require structured follow-up.","reference_text":"2023 ESC Acute Coronary Syndromes Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/acute-coronary-syndromes/","dr_corazon_hint":"The coronary event is a signal to treat the whole risk profile, not only the culprit lesion.","display_order":48,"options":[{"key":"A","text":"Blood pressure, lipids, diabetes and smoking","correct":true},{"key":"B","text":"Eye colour","correct":false},{"key":"C","text":"Hand dominance","correct":false},{"key":"D","text":"Shoe size","correct":false}]},
  {"module_id":"basic-acute-coronary-syndromes","external_id":"basic-acs-049","stem":"A patient taking dual antiplatelet therapy reports black stools. What should be advised?","clinical_scenario":null,"topic":"Counselling","subtopic":"Bleeding safety","difficulty":"intermediate","explanation":"Black stools may indicate gastrointestinal bleeding and require urgent assessment; the patient should not make unsupervised antiplatelet changes.","reference_text":"2023 ESC Acute Coronary Syndromes Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/acute-coronary-syndromes/","dr_corazon_hint":"Balance two dangers: possible bleeding and possible stent thrombosis if treatment is stopped without advice.","display_order":49,"options":[{"key":"A","text":"Seek urgent assessment and do not stop treatment without clinician advice","correct":true},{"key":"B","text":"Ignore the symptom","correct":false},{"key":"C","text":"Double both antiplatelet doses","correct":false},{"key":"D","text":"Wait until the next annual visit","correct":false}]},
  {"module_id":"basic-acute-coronary-syndromes","external_id":"basic-acs-050","stem":"Why is rapid reperfusion emphasized in STEMI?","clinical_scenario":null,"topic":"Treatment","subtopic":"Time to reperfusion","difficulty":"foundation","explanation":"The duration of coronary occlusion determines the amount of irreversible myocardial injury; earlier reperfusion saves myocardium and improves outcomes.","reference_text":"2023 ESC Acute Coronary Syndromes Guidelines","reference_url":"https://www.escardio.org/guidelines/clinical-practice-guidelines/all-esc-practice-guidelines/acute-coronary-syndromes/","dr_corazon_hint":"The memorable principle is 'time is muscle'.","display_order":50,"options":[{"key":"A","text":"Earlier flow restoration limits myocardial necrosis","correct":true},{"key":"B","text":"Delay improves clot organization","correct":false},{"key":"C","text":"Troponin must normalize before PCI","correct":false},{"key":"D","text":"Symptoms should continue for observation","correct":false}]}
]
$questions$::jsonb) as x(
  module_id text, external_id text, stem text, clinical_scenario text,
  topic text, subtopic text, difficulty text, explanation text,
  reference_text text, reference_url text, dr_corazon_hint text,
  display_order integer, options jsonb
);

-- -----------------------------------------------------------------------------
-- Upsert questions and answer options
-- -----------------------------------------------------------------------------

insert into public.questions (
  module_id, external_id, question_type, stem, clinical_scenario,
  explanation, reference_text, reference_url, topic, subtopic, difficulty,
  default_seconds, points, negative_points, confidence_enabled,
  randomize_options, display_order, status, dr_corazon_hint
)
select
  s.module_id,
  s.external_id,
  'single_best_answer',
  s.stem,
  s.clinical_scenario,
  s.explanation,
  s.reference_text,
  s.reference_url,
  s.topic,
  s.subtopic,
  s.difficulty,
  60,
  1,
  0,
  true,
  true,
  s.display_order,
  'published',
  s.dr_corazon_hint
from acl_basic_question_seed s
on conflict (module_id, external_id) where external_id is not null do update set
  stem = excluded.stem,
  clinical_scenario = excluded.clinical_scenario,
  explanation = excluded.explanation,
  reference_text = excluded.reference_text,
  reference_url = excluded.reference_url,
  topic = excluded.topic,
  subtopic = excluded.subtopic,
  difficulty = excluded.difficulty,
  default_seconds = excluded.default_seconds,
  points = excluded.points,
  confidence_enabled = excluded.confidence_enabled,
  randomize_options = excluded.randomize_options,
  display_order = excluded.display_order,
  status = excluded.status,
  dr_corazon_hint = excluded.dr_corazon_hint,
  updated_at = now();

insert into public.question_options (
  question_id, option_key, option_text, is_correct, display_order, feedback
)
select
  q.id,
  o.key,
  o.text,
  o.correct,
  o.ord,
  case when o.correct then s.explanation else null end
from acl_basic_question_seed s
join public.questions q
  on q.module_id = s.module_id and q.external_id = s.external_id
cross join lateral jsonb_to_recordset(s.options) with ordinality
  as o(key text, text text, correct boolean, ord bigint)
on conflict (question_id, option_key) do update set
  option_text = excluded.option_text,
  is_correct = excluded.is_correct,
  display_order = excluded.display_order,
  feedback = excluded.feedback;

-- Attach all 50 questions to the matching published learning quiz.
insert into public.quiz_questions (quiz_id, question_id, display_order, is_required)
select z.id, q.id, q.display_order, true
from public.quizzes z
join public.questions q on q.module_id = z.module_id
where (z.module_id, z.slug) in (
  ('basic-heart-failure', 'basic-heart-failure-50'),
  ('basic-atrial-fibrillation', 'basic-atrial-fibrillation-50'),
  ('basic-acute-coronary-syndromes', 'basic-acute-coronary-syndromes-50')
)
and q.external_id like 'basic-%'
on conflict (quiz_id, question_id) do update set
  display_order = excluded.display_order,
  is_required = excluded.is_required;

-- Keep module counts synchronized with published question-bank content.
update public.modules m
set question_count = (
  select count(*)
  from public.questions q
  where q.module_id = m.id and q.status = 'published'
), updated_at = now()
where m.id in (
  'basic-heart-failure',
  'basic-atrial-fibrillation',
  'basic-acute-coronary-syndromes'
);

commit;

-- Verification summary: expected result is three rows, each with 50 questions.
select
  m.edition,
  m.title,
  m.access_type,
  m.status,
  count(q.id) filter (where q.status = 'published') as published_questions
from public.modules m
left join public.questions q on q.module_id = m.id
where m.id in (
  'basic-heart-failure',
  'basic-atrial-fibrillation',
  'basic-acute-coronary-syndromes'
)
group by m.edition, m.title, m.access_type, m.status
order by m.title;
